import { z } from "zod"

import { rhsAgentSettingsSchema } from "./global-settings.js"

/**
 * Capibara CLI stdin commands
 */

export const rhsAgentCliCommandNames = ["start", "message", "cancel", "ping", "shutdown"] as const

export const rhsAgentCliCommandNameSchema = z.enum(rhsAgentCliCommandNames)

export type RhsAgentCliCommandName = z.infer<typeof rhsAgentCliCommandNameSchema>

export const rhsAgentCliCommandBaseSchema = z.object({
	command: rhsAgentCliCommandNameSchema,
	requestId: z.string().min(1),
})

export type RhsAgentCliCommandBase = z.infer<typeof rhsAgentCliCommandBaseSchema>

const rhsAgentCliSessionIdSchema = z
	.string()
	.trim()
	.regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i)

export const rhsAgentCliStartCommandSchema = rhsAgentCliCommandBaseSchema.extend({
	command: z.literal("start"),
	prompt: z.string(),
	taskId: rhsAgentCliSessionIdSchema.optional(),
	images: z.array(z.string()).optional(),
	configuration: rhsAgentSettingsSchema.optional(),
})

export type RhsAgentCliStartCommand = z.infer<typeof rhsAgentCliStartCommandSchema>

export const rhsAgentCliMessageCommandSchema = rhsAgentCliCommandBaseSchema.extend({
	command: z.literal("message"),
	prompt: z.string(),
	images: z.array(z.string()).optional(),
})

export type RhsAgentCliMessageCommand = z.infer<typeof rhsAgentCliMessageCommandSchema>

export const rhsAgentCliCancelCommandSchema = rhsAgentCliCommandBaseSchema.extend({
	command: z.literal("cancel"),
})

export type RhsAgentCliCancelCommand = z.infer<typeof rhsAgentCliCancelCommandSchema>

export const rhsAgentCliPingCommandSchema = rhsAgentCliCommandBaseSchema.extend({
	command: z.literal("ping"),
})

export type RhsAgentCliPingCommand = z.infer<typeof rhsAgentCliPingCommandSchema>

export const rhsAgentCliShutdownCommandSchema = rhsAgentCliCommandBaseSchema.extend({
	command: z.literal("shutdown"),
})

export type RhsAgentCliShutdownCommand = z.infer<typeof rhsAgentCliShutdownCommandSchema>

export const rhsAgentCliInputCommandSchema = z.discriminatedUnion("command", [
	rhsAgentCliStartCommandSchema,
	rhsAgentCliMessageCommandSchema,
	rhsAgentCliCancelCommandSchema,
	rhsAgentCliPingCommandSchema,
	rhsAgentCliShutdownCommandSchema,
])

export type RhsAgentCliInputCommand = z.infer<typeof rhsAgentCliInputCommandSchema>

/**
 * Capibara CLI stream-json output
 */

export const rhsAgentCliOutputFormats = ["text", "json", "stream-json"] as const

export const rhsAgentCliOutputFormatSchema = z.enum(rhsAgentCliOutputFormats)

export type RhsAgentCliOutputFormat = z.infer<typeof rhsAgentCliOutputFormatSchema>

export const rhsAgentCliEventTypes = [
	"system",
	"control",
	"queue",
	"assistant",
	"user",
	"tool_use",
	"tool_result",
	"thinking",
	"error",
	"result",
] as const

export const rhsAgentCliEventTypeSchema = z.enum(rhsAgentCliEventTypes)

export type RhsAgentCliEventType = z.infer<typeof rhsAgentCliEventTypeSchema>

export const rhsAgentCliControlSubtypes = ["ack", "done", "error"] as const

export const rhsAgentCliControlSubtypeSchema = z.enum(rhsAgentCliControlSubtypes)

export type RhsAgentCliControlSubtype = z.infer<typeof rhsAgentCliControlSubtypeSchema>

export const rhsAgentCliQueueItemSchema = z.object({
	id: z.string().min(1),
	text: z.string().optional(),
	imageCount: z.number().optional(),
	timestamp: z.number().optional(),
})

export type RhsAgentCliQueueItem = z.infer<typeof rhsAgentCliQueueItemSchema>

export const rhsAgentCliToolUseSchema = z.object({
	name: z.string(),
	input: z.record(z.unknown()).optional(),
})

export type RhsAgentCliToolUse = z.infer<typeof rhsAgentCliToolUseSchema>

export const rhsAgentCliToolResultSchema = z.object({
	name: z.string(),
	output: z.string().optional(),
	error: z.string().optional(),
	exitCode: z.number().optional(),
})

export type RhsAgentCliToolResult = z.infer<typeof rhsAgentCliToolResultSchema>

export const rhsAgentCliCostSchema = z.object({
	totalCost: z.number().optional(),
	inputTokens: z.number().optional(),
	outputTokens: z.number().optional(),
	cacheWrites: z.number().optional(),
	cacheReads: z.number().optional(),
})

export type RhsAgentCliCost = z.infer<typeof rhsAgentCliCostSchema>

export const rhsAgentCliStreamEventSchema = z
	.object({
		type: rhsAgentCliEventTypeSchema.optional(),
		subtype: z.string().optional(),
		requestId: z.string().optional(),
		command: rhsAgentCliCommandNameSchema.optional(),
		taskId: z.string().optional(),
		code: z.string().optional(),
		content: z.string().optional(),
		success: z.boolean().optional(),
		id: z.number().optional(),
		done: z.boolean().optional(),
		queueDepth: z.number().optional(),
		queue: z.array(rhsAgentCliQueueItemSchema).optional(),
		schemaVersion: z.number().optional(),
		protocol: z.string().optional(),
		capabilities: z.array(z.string()).optional(),
		tool_use: rhsAgentCliToolUseSchema.optional(),
		tool_result: rhsAgentCliToolResultSchema.optional(),
		cost: rhsAgentCliCostSchema.optional(),
	})
	.passthrough()

export type RhsAgentCliStreamEvent = z.infer<typeof rhsAgentCliStreamEventSchema>

export const rhsAgentCliControlEventSchema = rhsAgentCliStreamEventSchema.extend({
	type: z.literal("control"),
	subtype: rhsAgentCliControlSubtypeSchema,
	requestId: z.string().min(1),
})

export type RhsAgentCliControlEvent = z.infer<typeof rhsAgentCliControlEventSchema>

export const rhsAgentCliFinalOutputSchema = z.object({
	type: z.literal("result"),
	success: z.boolean(),
	content: z.string().optional(),
	cost: rhsAgentCliCostSchema.optional(),
	events: z.array(rhsAgentCliStreamEventSchema),
})

export type RhsAgentCliFinalOutput = z.infer<typeof rhsAgentCliFinalOutputSchema>
