import { FileText } from "lucide-react"
import { splitFileMentions } from "../../utils/mentions"

export function MentionText({ text, onOpen }: { text: string; onOpen?: (path: string) => void }) {
	const parts = splitFileMentions(text)
	if (!parts.some((part) => part.mention)) return <>{text}</>
	return <>{parts.map((part, index) => part.mention
		? <button
			key={`${part.mention}-${index}`}
			type="button"
			className="capibara-file-mention"
			onClick={(event) => { event.stopPropagation(); onOpen?.(part.mention!) }}
			title={`Abrir ${part.mention.slice(2).replace(/\\ /g, " ")}`}>
			<FileText size={12} aria-hidden="true" />
			<span>{part.mention}</span>
		</button>
		: <span key={index}>{part.text}</span>)}</>
}
