import { createHighlighterCore, type HighlighterCore } from "shiki/core"
import { createJavaScriptRegexEngine } from "shiki/engine/javascript"
import r from "@shikijs/langs/r"
import python from "@shikijs/langs/python"
import shell from "@shikijs/langs/shellscript"
import javascript from "@shikijs/langs/javascript"
import typescript from "@shikijs/langs/typescript"
import json from "@shikijs/langs/json"
import markdown from "@shikijs/langs/markdown"
import yaml from "@shikijs/langs/yaml"
import css from "@shikijs/langs/css"
import html from "@shikijs/langs/html"
import sql from "@shikijs/langs/sql"
import diff from "@shikijs/langs/diff"
import githubDark from "@shikijs/themes/github-dark"
import githubLight from "@shikijs/themes/github-light"

export type ExtendedLanguage =
	| "r"
	| "python"
	| "shell"
	| "javascript"
	| "typescript"
	| "json"
	| "markdown"
	| "yaml"
	| "css"
	| "html"
	| "sql"
	| "diff"
	| "txt"

const languageAliases: Record<string, ExtendedLanguage> = {
	text: "txt",
	plaintext: "txt",
	plain: "txt",
	sh: "shell",
	bash: "shell",
	zsh: "shell",
	shellscript: "shell",
	console: "shell",
	terminal: "shell",
	js: "javascript",
	node: "javascript",
	nodejs: "javascript",
	ts: "typescript",
	py: "python",
	python3: "python",
	py3: "python",
	md: "markdown",
	yml: "yaml",
	htm: "html",
	jsonc: "json",
	json5: "json",
	css: "css",
	r: "r",
	rscript: "r",
	rmd: "markdown",
	qmd: "markdown",
	patch: "diff",
}

const languageModules = [
	r,
	python,
	shell,
	javascript,
	typescript,
	json,
	markdown,
	yaml,
	css,
	html,
	sql,
	diff,
]

const warnedLanguages = new Set<string>()
const supportedLanguages = new Set<ExtendedLanguage>([
	"r",
	"python",
	"shell",
	"javascript",
	"typescript",
	"json",
	"markdown",
	"yaml",
	"css",
	"html",
	"sql",
	"diff",
	"txt",
])

const state: {
	instance: HighlighterCore | null
	instanceInitPromise: Promise<HighlighterCore> | null
} = {
	instance: null,
	instanceInitPromise: null,
}

export function normalizeLanguage(language?: string): ExtendedLanguage {
	if (!language) return "txt"

	const normalized = language.toLowerCase()
	const resolved = languageAliases[normalized] ?? normalized
	if (supportedLanguages.has(resolved as ExtendedLanguage)) return resolved as ExtendedLanguage

	if (!warnedLanguages.has(language)) {
		console.warn(`[Shiki] Unrecognized language '${language}', defaulting to txt.`)
		warnedLanguages.add(language)
	}

	return "txt"
}

export function isLanguageLoaded(language: string): boolean {
	return supportedLanguages.has(normalizeLanguage(language))
}

export async function getHighlighter(_language?: string): Promise<HighlighterCore> {
	if (!state.instanceInitPromise) {
		state.instanceInitPromise = createHighlighterCore({
			themes: [githubLight, githubDark],
			langs: languageModules,
			engine: createJavaScriptRegexEngine(),
		}).then((instance) => {
			state.instance = instance
			return instance
		})
	}

	return state.instance ?? state.instanceInitPromise
}

export function preloadHighlighterLanguages(_languages: string[] = ["r", "python", "shell"]): void {
	void getHighlighter().catch((error) => {
		console.warn("[Cuy] Could not initialize syntax highlighting:", error)
	})
}
