import { useEffect, useState } from "react"
import mermaid from "mermaid"

let configured = false

/** Mermaid renderer ported from the predecessor's Markdown block contract. */
export function MermaidBlock({ code }: { code: string }) {
	const [svg, setSvg] = useState<string>()
	const [error, setError] = useState<string>()

	useEffect(() => {
		let active = true
		if (!configured) {
			mermaid.initialize({ startOnLoad: false, securityLevel: "strict", theme: "base" })
			configured = true
		}
		const id = `capibara-mermaid-${Math.random().toString(36).slice(2, 10)}`
		setSvg(undefined)
		setError(undefined)
		void mermaid.render(id, code).then((result) => {
			if (active) setSvg(result.svg)
		}).catch((reason: unknown) => {
			if (active) setError(reason instanceof Error ? reason.message : String(reason))
		})
		return () => { active = false }
	}, [code])

	if (error) return <div className="markdown-mermaid-error"><strong>No se pudo renderizar el diagrama.</strong><pre>{error}</pre><code>{code}</code></div>
	if (svg) return <div className="markdown-mermaid" aria-label="Diagrama Mermaid" dangerouslySetInnerHTML={{ __html: svg }} />
	return <div className="markdown-mermaid" aria-label="Diagrama Mermaid"><span>Renderizando diagrama...</span></div>
}
