/* ------------------------------------------------------------------ */
/*  QuestionForm                                                       */
/* ------------------------------------------------------------------ */

function QuestionForm({ questions, questionOffset, language, onSubmit }: { questions: CapibaraQuestion[]; questionOffset: number; language: UiLanguage; onSubmit: (answers: Record<string, string | string[]>) => void }) {
	const [answers, setAnswers] = useState<Record<string, string | string[]>>({})
	const [submitted, setSubmitted] = useState(false)
	return (
		<div className="grid gap-3">
			{questions.map((item, index) => (
				<div key={`${index}-${item.question}`} className="chat-question-card" data-question-index={questionOffset + index}>
					<div className="mb-1 text-sm" style={{ fontFamily: "var(--vscode-font-family, system-ui, sans-serif)", color: "var(--vscode-foreground)" }}>
						{item.question}
					</div>
						{item.options?.length ? (
							<FollowUpSuggest
								suggestions={item.options.map((answer) => ({ answer }))}
								selected={answers[String(index)]}
								multiple={item.allowMultiple}
								language={language}
								onSelect={(option) => setAnswers((prev) => {
									if (!item.allowMultiple) return { ...prev, [String(index)]: option }
									const selected = Array.isArray(prev[String(index)]) ? prev[String(index)] as string[] : []
									return { ...prev, [String(index)]: selected.includes(option) ? selected.filter((value) => value !== option) : [...selected, option] }
								})}
							/>
					) : (
						<input
							disabled={submitted}
							onChange={(event) => setAnswers((prev) => ({ ...prev, [String(index)]: event.target.value }))}
							placeholder={t(language, "chat.answerPlaceholder")}
							style={answerInputStyle}
						/>
					)}
				</div>
			))}
			<button
				type="button"
				disabled={submitted}
				onClick={() => {
					setSubmitted(true)
					onSubmit(answers)
				}}
				style={approvalButtonStyle}>
				{t(language, "chat.sendAnswers")}
			</button>
		</div>
	)
}

/* ------------------------------------------------------------------ */
/*  Input extractors                                                   */
/* ------------------------------------------------------------------ */

function extractPath(message: CapibaraChatMessage): string | undefined {
	const input = message.toolInput
	if (!input) return undefined
	if (typeof input === "string") return input
	if (typeof input === "object" && input !== null) {
		const obj = input as Record<string, unknown>
		return typeof obj.path === "string" ? obj.path : typeof obj.filePath === "string" ? obj.filePath : undefined
	}
	return undefined
}

function extractCommand(message: CapibaraChatMessage): string | undefined {
	const input = message.toolInput
	if (!input) return undefined
	if (typeof input === "string") return input
	if (typeof input === "object" && input !== null) {
		const obj = input as Record<string, unknown>
		return typeof obj.command === "string" ? obj.command : typeof obj.cmd === "string" ? obj.cmd : undefined
	}
	return undefined
}

function extractCode(message: CapibaraChatMessage): string | undefined {
	const input = message.toolInput
	if (!input) return undefined
	if (typeof input === "string") return input
	if (typeof input === "object" && input !== null) {
		const obj = input as Record<string, unknown>
		return typeof obj.code === "string" ? obj.code : typeof obj.source === "string" ? obj.source : undefined
	}
	return undefined
}

function extractQuery(message: CapibaraChatMessage): string | undefined {
	const input = message.toolInput
	if (!input) return undefined
	if (typeof input === "string") return input
	if (typeof input === "object" && input !== null) {
		const obj = input as Record<string, unknown>
		return typeof obj.query === "string" ? obj.query : typeof obj.q === "string" ? obj.q : undefined
	}
	return undefined
}

function extractSkillName(message: CapibaraChatMessage): string | undefined {
	const input = message.toolInput
	if (!input) return undefined
	if (typeof input === "string") return input
	if (typeof input === "object" && input !== null) {
		const obj = input as Record<string, unknown>
		return typeof obj.skill === "string" ? obj.skill : typeof obj.name === "string" ? obj.name : undefined
	}
	return undefined
}

function inferLanguage(path?: string): string | undefined {
	if (!path) return undefined
	const ext = path.split(".").pop()?.toLowerCase()
	const map: Record<string, string> = {
		ts: "typescript", tsx: "tsx", js: "javascript", jsx: "jsx",
		py: "python", r: "r", rm: "r", rmd: "rmarkdown", qmd: "markdown",
		json: "json", yaml: "yaml", yml: "yaml", toml: "toml",
		md: "markdown", mdx: "mdx", html: "html", css: "css", scss: "scss",
		sh: "bash", bash: "bash", zsh: "bash",
		sql: "sql", xml: "xml", csv: "csv", txt: "plaintext",
		diff: "diff", patch: "diff",
	}
	return ext ? map[ext] : undefined
}

