import { z } from "zod"

import { RhsAgentEventName } from "./events.js"
import type { RhsAgentSettings } from "./global-settings.js"
import type { RhsMessage, QueuedMessage, TokenUsage } from "./message.js"
import type { ToolUsage, ToolName } from "./tool.js"
import type { TodoItem } from "./todo.js"

/**
 * TaskProviderLike
 */

export interface TaskProviderLike {
	// Tasks
	getCurrentTask(): TaskLike | undefined
	getRecentTasks(): string[]
	createTask(
		text?: string,
		images?: string[],
		parentTask?: TaskLike,
		options?: CreateTaskOptions,
		configuration?: RhsAgentSettings,
	): Promise<TaskLike>
	cancelTask(): Promise<void>
	clearTask(): Promise<void>
	resumeTask(taskId: string): void

	// Modes
	getModes(): Promise<{ slug: string; name: string }[]>
	getMode(): Promise<string>
	setMode(mode: string): Promise<void>

	// Provider Profiles
	getProviderProfiles(): Promise<{ name: string; provider?: string }[]>
	getProviderProfile(): Promise<string>
	setProviderProfile(providerProfile: string): Promise<void>

	readonly cwd: string

	// Event Emitter
	on<K extends keyof TaskProviderEvents>(
		event: K,
		listener: (...args: TaskProviderEvents[K]) => void | Promise<void>,
	): this

	off<K extends keyof TaskProviderEvents>(
		event: K,
		listener: (...args: TaskProviderEvents[K]) => void | Promise<void>,
	): this

	// @TODO: Find a better way to do this.
	postStateToWebview(): Promise<void>
}

export type TaskProviderEvents = {
	[RhsAgentEventName.TaskCreated]: [task: TaskLike]
	[RhsAgentEventName.TaskStarted]: [taskId: string]
	[RhsAgentEventName.TaskCompleted]: [taskId: string, tokenUsage: TokenUsage, toolUsage: ToolUsage]
	[RhsAgentEventName.TaskAborted]: [taskId: string]
	[RhsAgentEventName.TaskFocused]: [taskId: string]
	[RhsAgentEventName.TaskUnfocused]: [taskId: string]
	[RhsAgentEventName.TaskActive]: [taskId: string]
	[RhsAgentEventName.TaskInteractive]: [taskId: string]
	[RhsAgentEventName.TaskResumable]: [taskId: string]
	[RhsAgentEventName.TaskIdle]: [taskId: string]

	[RhsAgentEventName.TaskPaused]: [taskId: string]
	[RhsAgentEventName.TaskUnpaused]: [taskId: string]
	[RhsAgentEventName.TaskSpawned]: [taskId: string]
	[RhsAgentEventName.TaskDelegated]: [parentTaskId: string, childTaskId: string]
	[RhsAgentEventName.TaskDelegationCompleted]: [parentTaskId: string, childTaskId: string, summary: string]
	[RhsAgentEventName.TaskDelegationResumed]: [parentTaskId: string, childTaskId: string]

	[RhsAgentEventName.TaskUserMessage]: [taskId: string]

	[RhsAgentEventName.TaskTokenUsageUpdated]: [taskId: string, tokenUsage: TokenUsage, toolUsage: ToolUsage]

	[RhsAgentEventName.ModeChanged]: [mode: string]
	[RhsAgentEventName.ProviderProfileChanged]: [config: { name: string; provider?: string }]
}

/**
 * TaskLike
 */

export interface CreateTaskOptions {
	taskId?: string
	enableCheckpoints?: boolean
	consecutiveMistakeLimit?: number
	experiments?: Record<string, boolean>
	initialTodos?: TodoItem[]
	/** Initial status for the task's history item (e.g., "active" for child tasks) */
	initialStatus?: "active" | "delegated" | "completed" | "interrupted"
	/** Whether to start the task loop immediately (default: true).
	 *  When false, the caller must invoke `task.start()` manually. */
	startTask?: boolean
}

export enum TaskStatus {
	Running = "running",
	Interactive = "interactive",
	Resumable = "resumable",
	Idle = "idle",
	None = "none",
}

export const taskMetadataSchema = z.object({
	task: z.string().optional(),
	images: z.array(z.string()).optional(),
})

export type TaskMetadata = z.infer<typeof taskMetadataSchema>

export interface TaskLike {
	readonly taskId: string
	readonly rootTaskId?: string
	readonly parentTaskId?: string
	readonly childTaskId?: string
	readonly metadata: TaskMetadata
	readonly taskStatus: TaskStatus
	readonly taskAsk: RhsMessage | undefined
	readonly queuedMessages: QueuedMessage[]
	readonly tokenUsage: TokenUsage | undefined

	on<K extends keyof TaskEvents>(event: K, listener: (...args: TaskEvents[K]) => void | Promise<void>): this
	off<K extends keyof TaskEvents>(event: K, listener: (...args: TaskEvents[K]) => void | Promise<void>): this

	approveAsk(options?: { text?: string; images?: string[] }): void
	denyAsk(options?: { text?: string; images?: string[] }): void
	submitUserMessage(text: string, images?: string[], mode?: string, providerProfile?: string): Promise<void>
	abortTask(): void
}

export type TaskEvents = {
	// Task Lifecycle
	[RhsAgentEventName.TaskStarted]: []
	[RhsAgentEventName.TaskCompleted]: [taskId: string, tokenUsage: TokenUsage, toolUsage: ToolUsage]
	[RhsAgentEventName.TaskAborted]: []
	[RhsAgentEventName.TaskFocused]: []
	[RhsAgentEventName.TaskUnfocused]: []
	[RhsAgentEventName.TaskActive]: [taskId: string]
	[RhsAgentEventName.TaskInteractive]: [taskId: string]
	[RhsAgentEventName.TaskResumable]: [taskId: string]
	[RhsAgentEventName.TaskIdle]: [taskId: string]

	// Subtask Lifecycle
	[RhsAgentEventName.TaskPaused]: [taskId: string]
	[RhsAgentEventName.TaskUnpaused]: [taskId: string]
	[RhsAgentEventName.TaskSpawned]: [taskId: string]

	// Task Execution
	[RhsAgentEventName.Message]: [{ action: "created" | "updated"; message: RhsMessage }]
	[RhsAgentEventName.TaskModeSwitched]: [taskId: string, mode: string]
	[RhsAgentEventName.TaskAskResponded]: []
	[RhsAgentEventName.TaskUserMessage]: [taskId: string]
	[RhsAgentEventName.QueuedMessagesUpdated]: [taskId: string, messages: QueuedMessage[]]

	// Task Analytics
	[RhsAgentEventName.TaskToolFailed]: [taskId: string, tool: ToolName, error: string]
	[RhsAgentEventName.TaskTokenUsageUpdated]: [taskId: string, tokenUsage: TokenUsage, toolUsage: ToolUsage]
}
