/**
 * SettingsView — settings panel (provider/modelId/language + runners).
 *
 * Adaptado para funcionar como overlay panel con botón "Volver al chat".
 * Usa tokens de tema de VS Code para adaptarse a temas claros/oscuros.
 */

import { useEffect, useState } from "react"
import { ArrowLeft, RefreshCw, X } from "lucide-react"
import type { CapibaraState, WebviewToHost } from "../types/messages"
import { t } from "../i18n"
import { ChatGptAuthCard } from "./ChatGptAuthCard"

export interface SettingsViewProps {
	state: CapibaraState
	sendToHost: (msg: WebviewToHost) => void
	onClose: () => void
}

export function SettingsView({ state, sendToHost, onClose }: SettingsViewProps) {
	const isOllama = state.provider === "ollama"
	const providerSettings = state.providerSettings
	const addedProviders = ["gemini", "deepseek", "openai-codex", "openai-native", "mistral", "zai", "minimax", "qwen-code"]
	const usesBaseUrl = state.provider !== "openai-codex" && ["ollama", "lmstudio", "openai", "openai-compatible", "grok", ...addedProviders].includes(state.provider)
	const usesApiKey = state.provider !== "openai-codex" && ["ollama", "anthropic", "openai", "openai-compatible", "grok", ...addedProviders].includes(state.provider)
	const [apiKeyDraft, setApiKeyDraft] = useState("")

	useEffect(() => {
		setApiKeyDraft("")
		if (state.provider === "openai-codex") sendToHost({ type: "chatgptAuthStatus" })
	}, [state.provider])

	function requestOllamaModels() {
		sendToHost({ type: "requestOllamaModels" })
	}

	useEffect(() => {
		if (isOllama) requestOllamaModels()
		// Refresh when the user enters Ollama; the explicit button handles later refreshes.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [isOllama])

	function openSettings() {
		window.dispatchEvent(new CustomEvent("capibara-open-settings"))
	}

	const runners = [
		{ name: "pdfstruct", path: state.runners?.pdfstruct ?? "?" },
		{ name: "rhs-rag", path: state.runners?.rhsRag ?? "?" },
		{ name: "rhs-okf", path: state.runners?.rhsOkf ?? "?" },
		{ name: "obscura", path: state.runners?.obscura ?? "?" },
	]

	return (
		<div className="settings-view p-6 h-full overflow-y-auto scrollable" style={{ color: "var(--vscode-foreground)" }}>
			<header className="settings-header flex items-center gap-2 mb-6">
				<button
					type="button"
					onClick={onClose}
					title={t(state.language, "app.back")}
					aria-label={t(state.language, "app.back")}
					className="flex items-center justify-center h-7 w-7 rounded-md transition-colors"
					style={{
						background: "transparent",
						color: "var(--vscode-foreground)",
						border: "none",
						cursor: "pointer",
					}}>
					<ArrowLeft size={16} />
				</button>
				<h2 className="m-0 text-lg font-semibold">{t(state.language, "settings.title")}</h2>
			</header>

			<dl className="grid gap-x-6 gap-y-3" style={{ gridTemplateColumns: "max-content 1fr" }}>
				<dt style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.provider")}</dt>
				<dd>
					<code>{state.provider}</code>
				</dd>

				<dt style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.model")}</dt>
				<dd>
					<code>{state.modelId || t(state.language, "settings.emptyModel")}</code>
				</dd>

				<dt style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.language")}</dt>
				<dd>
					<code>{state.language}</code>
				</dd>

				<dt style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.apiStatus")}</dt>
				<dd>
					<span
						style={{
							color: state.apiReady ? "var(--vscode-charts-green)" : "var(--vscode-charts-yellow)",
							fontWeight: 500,
						}}>
						● {state.apiReady ? t(state.language, "settings.ready") : t(state.language, "settings.notReady")}
					</span>
				</dd>
			</dl>

			<h3 className="settings-section-title mt-8 mb-2 text-base">{t(state.language, "settings.runtime")}</h3>
			<div className="settings-section grid gap-3 max-w-xl">
				<label className="grid gap-1 text-sm">
					<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.provider")}</span>
					<select
						value={state.provider}
						onChange={(event) => {
							const provider = event.target.value
							sendToHost({ type: "updateSetting", setting: "provider", value: provider })
							if (provider === "ollama") requestOllamaModels()
						}}>
						{["ollama", "anthropic", "lmstudio", "openai", "openai-compatible", "grok", ...addedProviders].map((provider) => <option key={provider} value={provider}>{provider === "openai-codex" ? t(state.language, "chatgpt.title") : provider}</option>)}
					</select>
				</label>
				{state.provider === "openai-codex" && <ChatGptAuthCard state={state} sendToHost={sendToHost} />}
				{isOllama ? (
					<div className="grid gap-1 text-sm">
						<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.model")}</span>
						<div className="flex items-center gap-1">
							<select
								value={state.modelId}
								onChange={(event) => sendToHost({ type: "updateSetting", setting: "modelId", value: event.target.value })}
								className="min-w-0 flex-1">
								<option value="">{t(state.language, "settings.selectModel")}</option>
								{state.modelId && !state.ollamaModels.includes(state.modelId) && <option value={state.modelId}>{state.modelId} (configurado)</option>}
								{state.ollamaModels.map((model) => <option key={model} value={model}>{model}</option>)}
							</select>
							<button
								type="button"
								onClick={requestOllamaModels}
								title={t(state.language, "settings.refreshModels")}
								aria-label={t(state.language, "settings.refreshModels")}
								disabled={state.ollamaModelsLoading}
								className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border-0 bg-transparent text-[var(--vscode-foreground)] hover:bg-[var(--vscode-toolbar-hoverBackground)] disabled:opacity-50">
								<RefreshCw size={14} className={state.ollamaModelsLoading ? "animate-spin" : undefined} />
							</button>
						</div>
						<span className="text-xs" style={{ color: state.ollamaModelsError ? "var(--vscode-errorForeground)" : "var(--vscode-descriptionForeground)" }}>
							{state.ollamaModelsLoading
								? t(state.language, "settings.loadingModels")
								: state.ollamaModelsError ?? (state.ollamaModels.length > 0 ? `${state.ollamaModels.length} ${t(state.language, "settings.modelsAvailable")}` : t(state.language, "settings.noModels"))}
						</span>
					</div>
				) : (
					<label className="grid gap-1 text-sm">
						<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.model")}</span>
						<input value={providerSettings.modelId || state.modelId} onChange={(event) => sendToHost({ type: "updateSetting", setting: "modelId", value: event.target.value })} onBlur={(event) => sendToHost({ type: "updateSetting", setting: "modelId", value: event.target.value })} />
					</label>
				)}
				{usesBaseUrl && (
					<label className="grid gap-1 text-sm">
						<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.baseUrl")}</span>
						<input
							value={providerSettings.baseUrl ?? ""}
							onChange={(event) => sendToHost({ type: "updateSetting", setting: "baseUrl", value: event.target.value })}
							onBlur={(event) => sendToHost({ type: "updateSetting", setting: "baseUrl", value: event.target.value })}
							placeholder={state.provider === "lmstudio" ? "http://127.0.0.1:1234" : undefined}
						/>
					</label>
				)}
				{usesApiKey && (
					<label className="grid gap-1 text-sm">
						<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.apiKey")}</span>
						<div className="flex items-center gap-1">
							<input
								type="password"
								value={apiKeyDraft}
								onChange={(event) => setApiKeyDraft(event.target.value)}
								onBlur={() => {
									if (apiKeyDraft.trim()) sendToHost({ type: "updateSetting", setting: "apiKey", value: apiKeyDraft })
								}}
								placeholder={providerSettings.apiKeyConfigured ? t(state.language, "settings.apiKeyConfigured") : t(state.language, "settings.apiKeyPlaceholder")}
								autoComplete="off"
								className="min-w-0 flex-1"
							/>
							{providerSettings.apiKeyConfigured && (
								<button
									type="button"
									onClick={() => {
										setApiKeyDraft("")
										sendToHost({ type: "updateSetting", setting: "apiKey", value: "" })
									}}
									title={t(state.language, "settings.clearApiKey")}
									aria-label={t(state.language, "settings.clearApiKey")}
									className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border-0 bg-transparent text-[var(--vscode-foreground)] hover:bg-[var(--vscode-toolbar-hoverBackground)]">
									<X size={14} />
								</button>
							)}
						</div>
					</label>
				)}
				<label className="grid gap-1 text-sm">
					<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.language")}</span>
					<select value={state.language} onChange={(event) => sendToHost({ type: "updateSetting", setting: "language", value: event.target.value })}>
						<option value="es">es</option><option value="en">en</option>
					</select>
				</label>
			</div>

			<h3 className="settings-section-title mt-8 mb-2 text-base">{t(state.language, "settings.appearance")}</h3>
			<div className="settings-section grid gap-3 max-w-xl">
				<label className="grid gap-1 text-sm">
					<span style={{ color: "var(--vscode-descriptionForeground)" }}>{t(state.language, "settings.chatFontSize")}</span>
					<select value={state.chatFontSize} onChange={(event) => sendToHost({ type: "updateSetting", setting: "chat.fontSize", value: event.target.value })}>
						<option value="small">{t(state.language, "settings.fontSmall")}</option>
						<option value="normal">{t(state.language, "settings.fontNormal")}</option>
						<option value="large">{t(state.language, "settings.fontLarge")}</option>
						<option value="xlarge">{t(state.language, "settings.fontXLarge")}</option>
					</select>
				</label>
			</div>

			<h3 className="settings-section-title mt-8 mb-2 text-base">{t(state.language, "settings.approval")}</h3>
			<div className="settings-section grid gap-2 text-sm">
				<label className="grid gap-1 max-w-sm">
					<span>Perfil de acceso</span>
					<select value={state.accessPolicy.profile} onChange={(event) => sendToHost({ type: "updateSetting", setting: "permissions.profile", value: event.target.value })}>
						<option value="restricted">Restringido</option><option value="workspace">Workspace</option><option value="full">Full Access</option>
					</select>
				</label>
				<label className="grid gap-1 max-w-sm">
					<span>Política de aprobación</span>
					<select value={state.accessPolicy.approval} onChange={(event) => sendToHost({ type: "updateSetting", setting: "permissions.approval", value: event.target.value })}>
						<option value="always">Preguntar siempre</option><option value="sensitive">Solo sensibles</option><option value="never">No preguntar</option>
					</select>
				</label>
				{(["readOnly", "write", "execute"] as const).map((key) => (
					<label key={key} className="flex items-center gap-2">
						<input type="checkbox" checked={state.autoApproval?.[key] ?? false} onChange={(event) => sendToHost({ type: "updateSetting", setting: `autoApprove.${key}`, value: event.target.checked })} />
						{t(state.language, `settings.autoApprove.${key}` as never)}
					</label>
				))}
				<label className="flex items-center justify-between gap-3 max-w-sm">
					<span>{t(state.language, "settings.autoApprove.requestLimit" as never)}</span>
					<input
						type="number"
						min={1}
						step={1}
						value={state.autoApproval?.requestLimit ?? 100}
						onChange={(event) => sendToHost({ type: "updateSetting", setting: "autoApprove.requestLimit", value: Number(event.target.value) })}
						className="w-20"
					/>
				</label>
			</div>

			<h3 className="settings-section-title mt-8 mb-2 text-base" style={{ color: "var(--vscode-descriptionForeground)" }}>
				{t(state.language, "settings.runners")}
			</h3>
			<dl className="grid gap-x-6 gap-y-2" style={{ gridTemplateColumns: "max-content 1fr" }}>
				{runners.map((r) => (
					<Runner key={r.name} name={r.name} path={r.path} />
				))}
			</dl>
			<p className="mt-3 text-xs" style={{ color: "var(--vscode-descriptionForeground)" }}>
				{t(state.language, "settings.runnersHint")}
			</p>

			<p className="mt-6 text-sm" style={{ color: "var(--vscode-descriptionForeground)" }}>
				{t(state.language, "settings.editHint")}
			</p>
			<button
				type="button"
				onClick={openSettings}
				className="mt-2 rounded-md px-4 py-2 text-sm transition-colors"
				style={{
					background: "var(--vscode-button-background)",
					color: "var(--vscode-button-foreground)",
					border: "none",
					cursor: "pointer",
				}}>
				{t(state.language, "settings.openSettings")}
			</button>
		</div>
	)
}

function Runner({ name, path }: { name: string; path: string }) {
	const isUnresolved = path === "?" || path === name
	return (
		<>
			<dt
				className="text-sm"
				style={{
					color: "var(--vscode-descriptionForeground)",
					fontFamily: "var(--vscode-editor-font-family, monospace)",
				}}>
				{name}
			</dt>
			<dd
				className="text-xs break-all"
				style={{
					fontFamily: "var(--vscode-editor-font-family, monospace)",
					color: isUnresolved ? "var(--vscode-charts-yellow)" : "var(--vscode-descriptionForeground)",
				}}>
				{path}
			</dd>
		</>
	)
}
