import { RotateCcw, X } from "lucide-react"

export function CheckpointRestoreDialog({ open, onCancel, onConfirm }: { open: boolean; onCancel: () => void; onConfirm: () => void }) {
	if (!open) return null
	return (
		<div className="fixed inset-0 z-50 flex items-center justify-center px-4" role="dialog" aria-modal="true" aria-labelledby="checkpoint-dialog-title" style={{ background: "rgba(0, 0, 0, 0.35)" }}>
			<div className="w-full max-w-sm p-4" style={{ background: "var(--vscode-editorWidget-background)", color: "var(--vscode-foreground)", border: "1px solid var(--vscode-panel-border, transparent)", borderRadius: 6, boxShadow: "0 8px 30px rgba(0, 0, 0, 0.25)" }}>
				<div className="flex items-center gap-2 mb-2"><RotateCcw size={16} /><strong id="checkpoint-dialog-title">Restaurar archivos</strong><button type="button" onClick={onCancel} aria-label="Cancelar" className="ml-auto" style={{ background: "transparent", color: "inherit", border: "none", cursor: "pointer" }}><X size={15} /></button></div>
				<p className="text-sm mb-4" style={{ color: "var(--vscode-descriptionForeground)" }}>Los archivos volverán al estado guardado en este punto. El historial del chat se conservará.</p>
				<div className="flex justify-end gap-2"><button type="button" onClick={onCancel} style={{ background: "transparent", color: "var(--vscode-foreground)", border: "1px solid var(--vscode-input-border, transparent)", borderRadius: 3, padding: "4px 10px", cursor: "pointer" }}>Cancelar</button><button type="button" onClick={onConfirm} style={{ background: "var(--vscode-button-background)", color: "var(--vscode-button-foreground)", border: "none", borderRadius: 3, padding: "4px 10px", cursor: "pointer" }}>Restaurar</button></div>
			</div>
		</div>
	)
}
