/**
 * HistoryView — lista de tareas guardadas (resume/delete).
 *
 * Adaptado para funcionar como overlay panel (con botón de cierre) o como
 * vista standalone. El host responde a `requestTasks` con `tasks`
 * (CapibaraTaskSummary[]). Resume envía `resumeTask`.
 */

import { useEffect, useState } from "react"
import { ArrowLeft, Clock, Download, MessageSquare, Play, Search, Trash2, Upload } from "lucide-react"
import type { CapibaraTaskSummary, WebviewToHost } from "../types/messages"
import { t, type UiLanguage } from "../i18n"

export interface HistoryViewProps {
	language: UiLanguage
	tasks: CapibaraTaskSummary[]
	activeTaskId: string
	sendToHost: (msg: WebviewToHost) => void
	onClose: () => void
}

function formatTime(ts: number): string {
	const d = new Date(ts)
	return d.toLocaleString()
}

export function HistoryView({ language, tasks, activeTaskId, sendToHost, onClose }: HistoryViewProps) {
	const [query, setQuery] = useState("")

	useEffect(() => {
		const timeout = window.setTimeout(() => sendToHost({ type: "requestTasks", query }), 180)
		return () => window.clearTimeout(timeout)
	}, [query, sendToHost])

	return (
		<div className="history-view flex flex-col h-full overflow-y-auto scrollable">
			<div className="history-header flex items-center gap-2 px-4 py-3 border-b" style={{ borderColor: "var(--vscode-editorGroup-border, transparent)" }}>
				<button
					type="button"
					onClick={onClose}
					title={t(language, "app.back")}
					aria-label={t(language, "app.back")}
					className="flex items-center justify-center h-7 w-7 rounded-md transition-colors"
					style={{
						background: "transparent",
						color: "var(--vscode-foreground)",
						border: "none",
						cursor: "pointer",
					}}>
					<ArrowLeft size={16} />
				</button>
				<h2 className="m-0 text-base font-semibold" style={{ color: "var(--vscode-foreground)" }}>
					{t(language, "history.title")}
				</h2>
				<button type="button" onClick={() => sendToHost({ type: "importTask" })} title="Importar tarea" aria-label="Importar tarea" className="ml-auto flex items-center justify-center h-7 w-7 rounded-md" style={{ background: "transparent", color: "var(--vscode-foreground)", border: "1px solid var(--vscode-input-border, transparent)", cursor: "pointer" }}><Upload size={14} /></button>
			</div>
			<label className="history-search relative mx-3 mt-3">
				<Search
					size={14}
					className="absolute left-2 top-1/2 -translate-y-1/2"
					style={{ color: "var(--vscode-input-placeholderForeground)" }}
				/>
				<input
					type="search"
					value={query}
					onChange={(event) => setQuery(event.target.value)}
					placeholder={t(language, "history.search")}
					className="w-full h-8 pl-8 pr-2 text-sm"
					style={{
						background: "var(--vscode-input-background)",
						color: "var(--vscode-input-foreground)",
						border: "1px solid var(--vscode-input-border, transparent)",
					}}
				/>
			</label>

			{tasks.length === 0 ? (
				<div className="flex-1 flex items-center justify-center p-6">
					<p className="m-0 text-sm" style={{ color: "var(--vscode-descriptionForeground)" }}>
						{t(language, "history.empty")}
					</p>
				</div>
			) : (
				<div className="history-list flex flex-col gap-2 p-3">
					{tasks.map((task) => {
						const isActive = task.id === activeTaskId
						return (
							<div
								key={task.id}
								className={`history-item border p-3 flex items-center gap-3${isActive ? " is-active" : ""}`}
								style={{
									background: isActive ? "var(--vscode-list-activeSelectionBackground)" : "var(--vscode-editor-background)",
									borderColor: "var(--vscode-input-border, transparent)",
								}}>
								<div className="flex-1 min-w-0">
									<p
										className="m-0 text-sm truncate"
										style={{
											color: isActive ? "var(--vscode-list-activeSelectionForeground)" : "var(--vscode-foreground)",
										}}>
										{task.title || task.preview || task.id}
									</p>
									{task.matchPreview ? (
										<p className="m-0 mt-1 text-xs line-clamp-2" style={{ color: "var(--vscode-descriptionForeground)" }}>
											{task.matchPreview}
										</p>
									) : null}
									<div className="flex items-center gap-3 mt-1 text-xs" style={{ color: "var(--vscode-descriptionForeground)" }}>
										<span className="flex items-center gap-1">
											<MessageSquare size={12} />
											{task.messageCount} {t(language, "history.messages")}
										</span>
										<span className="flex items-center gap-1">
											<Clock size={12} />
											{formatTime(task.updatedAt)}
										</span>
									</div>
								</div>
								<button
									type="button"
									onClick={() => {
										sendToHost({ type: "resumeTask", taskId: task.id })
										onClose()
									}}
									title={t(language, "history.resume")}
									className="flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs transition-colors"
									style={{
										background: "var(--vscode-button-background)",
										color: "var(--vscode-button-foreground)",
										border: "none",
										cursor: "pointer",
									}}>
									<Play size={12} />
									{t(language, "history.resume")}
								</button>
								<button type="button" onClick={() => sendToHost({ type: "exportTask", taskId: task.id })} title="Exportar tarea" aria-label="Exportar tarea" className="flex items-center justify-center h-8 w-8 rounded-md" style={{ background: "transparent", color: "var(--vscode-foreground)", border: "1px solid var(--vscode-input-border, transparent)", cursor: "pointer" }}><Download size={14} /></button>
								<button
									type="button"
									onClick={() => { if (window.confirm(t(language, "history.confirmDelete"))) sendToHost({ type: "deleteTask", taskId: task.id }) }}
									title={t(language, "history.delete")}
									aria-label={t(language, "history.delete")}
									className="flex items-center justify-center h-8 w-8 rounded-md"
									style={{ background: "transparent", color: "var(--vscode-errorForeground)", border: "1px solid var(--vscode-input-border, transparent)", cursor: "pointer" }}>
									<Trash2 size={14} />
								</button>
							</div>
						)
					})}
				</div>
			)}
		</div>
	)
}
