import { useState } from "react"
import { Download, ExternalLink, Maximize2, X } from "lucide-react"
import type { WebviewToHost } from "../../types/messages"

export function ImageViewer({ dataUri, alt, sendToHost }: { dataUri: string; alt: string; sendToHost?: (message: WebviewToHost) => void }) {
	const [open, setOpen] = useState(false)
	const [zoom, setZoom] = useState(1)
	const send = (message: WebviewToHost) => sendToHost?.(message)
	return (
		<>
			<div className="relative inline-block max-w-full group">
				<img src={dataUri} alt={alt} onClick={() => { setOpen(true); setZoom(1) }} className="mt-2 max-h-96 max-w-full rounded object-contain cursor-zoom-in" />
				<div className="absolute right-1 top-3 hidden group-hover:flex items-center gap-1 p-1" style={{ background: "var(--vscode-editorWidget-background)", borderRadius: 3 }}>
					<button type="button" title="Abrir imagen" aria-label="Abrir imagen" onClick={() => setOpen(true)} className="p-1" style={{ color: "var(--vscode-foreground)", background: "transparent", border: "none", cursor: "pointer" }}><Maximize2 size={13} /></button>
					<button type="button" title="Abrir en el editor" aria-label="Abrir en el editor" onClick={() => send({ type: "openImage", dataUri })} className="p-1" style={{ color: "var(--vscode-foreground)", background: "transparent", border: "none", cursor: "pointer" }}><ExternalLink size={13} /></button>
					<button type="button" title="Guardar imagen" aria-label="Guardar imagen" onClick={() => send({ type: "saveImage", dataUri })} className="p-1" style={{ color: "var(--vscode-foreground)", background: "transparent", border: "none", cursor: "pointer" }}><Download size={13} /></button>
				</div>
			</div>
			{open && <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-label={alt} style={{ background: "rgba(0, 0, 0, 0.78)" }} onClick={() => setOpen(false)}>
				<div className="relative max-w-full max-h-full" onClick={(event) => event.stopPropagation()}>
					<div className="absolute right-1 top-1 z-10 flex gap-1"><button type="button" title="Alejar" onClick={() => setZoom((value) => Math.max(0.5, value - 0.25))} className="px-2 py-1" style={{ background: "var(--vscode-editorWidget-background)", color: "var(--vscode-foreground)", border: "none", cursor: "pointer" }}>−</button><button type="button" title="Acercar" onClick={() => setZoom((value) => Math.min(4, value + 0.25))} className="px-2 py-1" style={{ background: "var(--vscode-editorWidget-background)", color: "var(--vscode-foreground)", border: "none", cursor: "pointer" }}>+</button><button type="button" title="Guardar imagen" onClick={() => send({ type: "saveImage", dataUri })} className="p-1" style={{ background: "var(--vscode-editorWidget-background)", color: "var(--vscode-foreground)", border: "none", cursor: "pointer" }}><Download size={14} /></button><button type="button" title="Cerrar" onClick={() => setOpen(false)} className="p-1" style={{ background: "var(--vscode-editorWidget-background)", color: "var(--vscode-foreground)", border: "none", cursor: "pointer" }}><X size={14} /></button></div>
					<img src={dataUri} alt={alt} style={{ transform: `scale(${zoom})`, transformOrigin: "center", maxWidth: "90vw", maxHeight: "85vh", objectFit: "contain" }} />
				</div>
			</div>}
		</>
	)
}
