/**
 * ChatView — lista de mensajes + ChatTextArea.
 *
 * Layout full-screen estilo predecesor: ocupa todo el viewport.
 * TaskHeader cuando hay mensajes. WelcomeView cuando no hay mensajes.
 * Los botones de Settings/History se movieron al TopBar (navegación por tabs).
 */

import { useEffect, useRef, useState } from "react"
import { ChevronDown, LoaderCircle, Pencil, X } from "lucide-react"
import type { ChatFontSize, CapibaraActivity, CapibaraChatMessage, CapibaraContextUsage, CapibaraMentionFile, CapibaraQuestion, CapibaraSlashCommand, CapibaraTaskSummary, WebviewToHost } from "../types/messages"
import { ChatRow } from "./ChatRow"
import { ChatTextArea } from "./ChatTextArea"
import { TaskHeader } from "./TaskHeader"
import { ContextWindowProgress } from "./common/ContextWindowProgress"
import { WelcomeView } from "./WelcomeView"
import { t, type UiLanguage } from "../i18n"

export interface ChatViewProps {
	messages: CapibaraChatMessage[]
	sendToHost: (msg: WebviewToHost) => void
	language: UiLanguage
	chatFontSize: ChatFontSize
	webEnabled: boolean
	mode: string
	modes: Array<{ slug: string; label: string; description: string }>
	slashCommands?: CapibaraSlashCommand[]
	mentionFiles?: { query: string; requestId: string; items: CapibaraMentionFile[] }
	tasks?: CapibaraTaskSummary[]
	queuedCount?: number
	queuedMessages?: Array<{ id: string; timestamp: number; text: string; images?: string[] }>
	onShowHistory?: () => void
	streaming?: boolean
	activity?: CapibaraActivity
	contextUsage?: CapibaraContextUsage
	selectedImages?: string[]
	onSelectImages?: () => void
	onClearImages?: () => void
	retryableUserId?: string
}

export function ChatView({ messages, sendToHost, language, chatFontSize, webEnabled, mode, modes, slashCommands, mentionFiles, tasks, queuedCount = 0, queuedMessages = [], onShowHistory, streaming, activity, contextUsage, retryableUserId, selectedImages = [], onSelectImages }: ChatViewProps) {
	const listRef = useRef<HTMLDivElement | null>(null)
	const followTailRef = useRef(true)
	const [showScrollToBottom, setShowScrollToBottom] = useState(false)

	useEffect(() => {
		const el = listRef.current
		if (!el || !followTailRef.current) return
		el.scrollTop = el.scrollHeight
		setShowScrollToBottom(false)
	}, [messages])

	function handleScroll(): void {
		const el = listRef.current
		if (!el) return
		const atBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 32
		followTailRef.current = atBottom
		setShowScrollToBottom(!atBottom && el.scrollHeight > el.clientHeight)
	}

	function scrollToBottom(): void {
		const el = listRef.current
		if (!el) return
		followTailRef.current = true
		el.scrollTo({ top: el.scrollHeight, behavior: "smooth" })
		setShowScrollToBottom(false)
	}

	function handleSend(text: string) {
		const images = selectedImages.length ? { images: selectedImages } : {}
		sendToHost(streaming ? { type: "queueMessage", text, ...images } : { type: "chatMessage", text, ...images })
	}

	function jumpToQuestion(index: number): void {
		const root = listRef.current
		if (!root) return
		const direct = root.querySelector<HTMLElement>(`[data-question-index="${index}"]`)
		const group = Array.from(root.querySelectorAll<HTMLElement>("[data-question-group-start]"))
			.filter((element) => Number(element.dataset.questionGroupStart) <= index)
			.sort((left, right) => Number(right.dataset.questionGroupStart) - Number(left.dataset.questionGroupStart))[0]
		const target = direct ?? group
		if (!target) return
		target.scrollIntoView({ behavior: "smooth", block: "center" })
	}

	const hasMessages = messages.length > 0
	const modeLabel = modes.find((m) => m.slug === mode)?.label ?? mode
	const questionCount = messages.reduce((total, message) => total + countQuestions(message), 0)
	let questionOffset = 0

	return (
		<div className={`chat-view chat-font-${chatFontSize} flex flex-col h-full min-h-0`}>
			{/* TaskHeader — visible when there are messages */}
			{hasMessages && (
				<TaskHeader
					mode={mode}
					modeLabel={modeLabel}
					messages={messages}
					language={language}
					onNewTask={() => sendToHost({ type: "newTask" })}
					onCondense={() => sendToHost({ type: "condenseTaskContextRequest" })}
					onCancel={() => sendToHost({ type: "cancelTask" })}
					streaming={streaming}
					contextUsage={contextUsage}
					onOpenMention={(path) => sendToHost({ type: "openMention", path })}
				/>
			)}

			<div ref={listRef} onScroll={handleScroll} className="chat-scroll-region relative flex-1 overflow-y-auto scrollable min-h-0">
				{!hasMessages ? (
					<WelcomeView language={language} tasks={tasks} onShowHistory={onShowHistory} />
				) : (
					<div className="chat-message-list flex flex-col gap-2 px-3 py-2">
						{messages.map((m) => {
							const currentQuestionOffset = questionOffset
							questionOffset += countQuestions(m)
							return <ChatRow
								key={m.id}
								language={language}
								message={m}
								retryable={m.id === retryableUserId}
								isLatest={m.role === "assistant" && m.id === messages.filter((message) => message.role === "assistant").at(-1)?.id}
								onApprove={(approved) => {
									if (m.toolCallId) sendToHost({ type: "toolApproval", callId: m.toolCallId, approved })
								}}
								onQuestionSubmit={(answers) => {
									if (m.toolCallId) sendToHost({ type: "userQuestionResponse", callId: m.toolCallId, answers })
								}}
								onEditMessage={(text) => sendToHost({ type: "editMessage", messageIndex: m.messageIndex ?? -1, text })}
								onDeleteMessage={() => sendToHost({ type: "deleteMessage", messageIndex: m.messageIndex ?? -1 })}
								onRetryMessage={() => sendToHost({ type: "retryMessage", messageIndex: m.messageIndex ?? -1 })}
								onFeedback={(value) => sendToHost({ type: "assistantFeedback", messageIndex: m.messageIndex ?? -1, value })}
								onBranchMessage={() => sendToHost({ type: "branchMessage", messageIndex: m.messageIndex ?? -1 })}
								onExportQmd={(mode) => sendToHost({ type: "exportQmd", messageIndex: m.messageIndex ?? -1, mode })}
								onRestoreCheckpoint={() => sendToHost({ type: "restoreCheckpoint", messageIndex: m.messageIndex ?? -1 })}
								questionOffset={currentQuestionOffset}
								sendToHost={sendToHost}
							/>
						})}
						</div>
				)}
				{questionCount > 1 && (
					<div className="question-navigator" role="navigation" aria-label={t(language, "chat.questionNavigator")}>
						{Array.from({ length: questionCount }, (_, index) => (
							<button key={index} type="button" onClick={() => jumpToQuestion(index)} title={t(language, "chat.goToQuestion").replace("{number}", String(index + 1))} aria-label={t(language, "chat.goToQuestion").replace("{number}", String(index + 1))}>
								{index + 1}
							</button>
						))}
					</div>
				)}
				{showScrollToBottom && (
					<button type="button" className="chat-scroll-to-bottom" onClick={scrollToBottom} title={t(language, "chat.scrollToBottom")} aria-label={t(language, "chat.scrollToBottom")}>
						<ChevronDown size={15} />
					</button>
				)}
			</div>

			{contextUsage && <ContextWindowProgress usage={contextUsage} language={language} />}
			{(activity || streaming) && <ActivityLine activity={activity ?? { kind: "thinking" }} language={language} />}
			{queuedCount > 0 && (
				<div className="capibara-queued-status" role="status" aria-live="polite">
					<span>{queuedCount} {queuedCount === 1 ? t(language, "chat.queuedMessage") : t(language, "chat.queuedMessages")}</span>
					{queuedMessages.map((queued) => <QueuedMessageRow key={queued.id} queued={queued} sendToHost={sendToHost} />)}
				</div>
			)}

			<ChatTextArea
				language={language}
				chatFontSize={chatFontSize}
				webEnabled={webEnabled}
				mode={mode}
				modes={modes}
				slashCommands={slashCommands ?? []}
				mentionFiles={mentionFiles}
				sendToHost={sendToHost}
				onSend={handleSend}
				onCancel={() => sendToHost({ type: "cancelTask" })}
				onSelectImages={onSelectImages}
				selectedImages={selectedImages}
				streaming={streaming}
			/>
		</div>
	)
}

function QueuedMessageRow({ queued, sendToHost }: { queued: { id: string; text: string; images?: string[] }; sendToHost: (message: WebviewToHost) => void }) {
	return <div className="capibara-queued-message flex items-center gap-1 mt-1">
		<span className="truncate flex-1">{queued.text || "[imagen]"}</span>
		<button type="button" title="Editar mensaje en cola" aria-label="Editar mensaje en cola" onClick={() => { const text = window.prompt("Editar mensaje", queued.text); if (text !== null) sendToHost({ type: "editQueuedMessage", payload: { id: queued.id, text, images: queued.images } }) }}><Pencil size={12} /></button>
		<button type="button" title="Quitar mensaje de la cola" aria-label="Quitar mensaje de la cola" onClick={() => sendToHost({ type: "removeQueuedMessage", id: queued.id })}><X size={12} /></button>
	</div>
}

function countQuestions(message: CapibaraChatMessage): number {
	if (message.role !== "tool" || message.toolName !== "ask_user_question" || !Array.isArray(message.toolInput)) return 0
	return (message.toolInput as CapibaraQuestion[]).filter((item) => item && typeof item.question === "string").length
}

function activityLabel(activity: CapibaraActivity, language: UiLanguage): string {
	if (activity.kind === "thinking") return t(language, "chat.thinking")
	if (activity.kind === "responding") return t(language, "chat.responding")
	switch (activity.toolName) {
		case "read_file": return t(language, "chat.readingFile")
		case "list_files": return t(language, "chat.listingDir")
		case "execute_command": return t(language, "chat.executingCommand")
		case "execute_code": return t(language, "chat.executingCode")
		case "document_search": return t(language, "chat.searchingDocs")
		case "web_search": return t(language, "chat.searchingWeb")
		case "web_fetch": return t(language, "chat.fetchingUrl")
		case "load_skill": return t(language, "chat.loadingSkill")
		case "skill": return t(language, "chat.loadingSkill")
		case "write_to_file": return t(language, "chat.writingFile")
		case "replace_in_file": return t(language, "chat.editingFile")
		case "process_pdf": return t(language, "chat.processingDocument")
		case "inspect_variables": return t(language, "chat.inspectingVariables")
		case "view_plot": return t(language, "chat.viewingPlot")
		case "get_table_summary": return t(language, "chat.summarizingTable")
		case "ask_user_question": return t(language, "chat.askingQuestion")
		default: return t(language, "chat.thinking")
	}
}

function ActivityLine({ activity, language }: { activity: CapibaraActivity; language: UiLanguage }) {
	const phase = `${activity.kind}:${activity.toolName ?? ""}`
	const [elapsed, setElapsed] = useState(0)
	const startedAt = useRef<number | undefined>()

	useEffect(() => {
		startedAt.current = Date.now()
		setElapsed(0)
		const timer = window.setInterval(() => {
			setElapsed(Math.floor((Date.now() - (startedAt.current ?? Date.now())) / 1000))
		}, 1000)
		return () => window.clearInterval(timer)
	}, [phase])

	return (
		<div className="capibara-live-progress flex items-center gap-2 px-2 py-1.5 text-xs" style={{ color: "var(--vscode-descriptionForeground)" }} role="status" aria-live="polite">
			<LoaderCircle size={13} className="animate-spin" aria-hidden="true" />
			<span>{activity.detail || activityLabel(activity, language)}</span>
			<span className="capibara-live-progress-elapsed" aria-label={`${elapsed} segundos`}>{elapsed}s</span>
		</div>
	)
}
