import { memo, useEffect, useMemo, useState, type ReactNode } from "react"
import { structuredPatch, type Hunk as DiffHunk } from "diff"
import { ChevronDown, ChevronRight } from "lucide-react"
import { Fragment, jsx, jsxs } from "react/jsx-runtime"
import { toJsxRuntime } from "hast-util-to-jsx-runtime"
import type { Element, Root } from "hast"
import type { CapibaraApprovalPreviewFile } from "../../types/messages"
import { getHighlighter, normalizeLanguage } from "../../utils/highlighter"

interface DiffLine {
	oldLineNum: number | null
	newLineNum: number | null
	type: "context" | "addition" | "deletion" | "gap"
	content: string
	hiddenCount?: number
}

interface Hunk {
	lines: DiffLine[]
	oldText: string
	newText: string
	highlightedOldLines?: ReactNode[]
	highlightedNewLines?: ReactNode[]
}

function languageForPath(filePath: string): string {
	const extension = filePath.split(".").pop()?.toLowerCase() ?? "txt"
	const languages: Record<string, string> = {
		js: "javascript", jsx: "javascript", ts: "typescript", tsx: "typescript",
		py: "python", r: "r", rmd: "markdown", qmd: "markdown", md: "markdown",
		json: "json", yaml: "yaml", yml: "yaml", sh: "shell", bash: "shell",
		css: "css", html: "html", htm: "html", sql: "sql",
	}
	return normalizeLanguage(languages[extension] ?? "txt")
}

function parseLines(file: CapibaraApprovalPreviewFile): Hunk[] {
	const patch = structuredPatch(file.path, file.path, file.original, file.updated, "", "", { context: 3 })
	return patch.hunks.map((hunk: DiffHunk, hunkIndex: number) => {
		const lines: DiffLine[] = []
		if (hunkIndex > 0) {
			const previous = patch.hunks[hunkIndex - 1]!
			const hidden = Math.max(
				hunk.oldStart - (previous.oldStart + previous.oldLines),
				hunk.newStart - (previous.newStart + previous.newLines),
			)
			if (hidden > 0) lines.push({ oldLineNum: null, newLineNum: null, type: "gap", content: "", hiddenCount: hidden })
		}

		let oldLine = hunk.oldStart
		let newLine = hunk.newStart
		for (const raw of hunk.lines) {
			const content = raw.slice(1)
			if (raw.startsWith("-")) lines.push({ oldLineNum: oldLine++, newLineNum: null, type: "deletion", content })
			else if (raw.startsWith("+")) lines.push({ oldLineNum: null, newLineNum: newLine++, type: "addition", content })
			else lines.push({ oldLineNum: oldLine++, newLineNum: newLine++, type: "context", content })
		}

		const oldLines = lines.filter((line) => line.type === "deletion" || line.type === "context").map((line) => line.content)
		const newLines = lines.filter((line) => line.type === "addition" || line.type === "context").map((line) => line.content)
		return { lines, oldText: oldLines.join("\n"), newText: newLines.join("\n") }
	})
}

async function highlightText(text: string, language: string, theme: "light" | "dark"): Promise<ReactNode[]> {
	const sourceLines = text.split("\n")
	if (!text.trim()) return sourceLines
	try {
		const highlighter = await getHighlighter(language)
		const hast = highlighter.codeToHast(text, {
			lang: language,
			theme: theme === "light" ? "github-light" : "github-dark",
			transformers: [{ pre(node: Element) { node.properties.style = "padding:0;margin:0;background:none"; return node } }],
		}) as Root
		const pre = hast.children[0]
		if (!pre || pre.type !== "element") return sourceLines
		const code = pre.children[0]
		if (!code || code.type !== "element") return sourceLines
		const lines = code.children.filter((node): node is Element => node.type === "element" && node.tagName === "span" && hasClass(node, "line"))
		if (lines.length !== sourceLines.length) return sourceLines
		return lines.map((line) => toJsxRuntime(
			{ type: "root", children: [{ type: "element", tagName: "span", properties: {}, children: line.children }] },
			{ Fragment, jsx, jsxs },
		))
	} catch {
		return sourceLines
	}
}

function hasClass(node: Element, className: string): boolean {
	const value = node.properties.className
	return Array.isArray(value) && value.includes(className)
}

export const DiffView = memo(function DiffView({ files }: { files: CapibaraApprovalPreviewFile[] }) {
	return <div className="capibara-diff-view" aria-label="Vista previa de cambios">{files.map((file) => <DiffFile key={`${file.operation}:${file.path}`} file={file} />)}</div>
})

function DiffFile({ file }: { file: CapibaraApprovalPreviewFile }) {
	const [open, setOpen] = useState(true)
	const [processedHunks, setProcessedHunks] = useState<Hunk[]>([])
	const hunks = useMemo(() => parseLines(file), [file])
	const language = useMemo(() => languageForPath(file.path), [file.path])
	const shouldHighlight = file.original.split("\n").length + file.updated.split("\n").length <= 1000
	const isLightTheme = typeof document !== "undefined" && /\bvscode-light\b|\bvscode-high-contrast-light\b/i.test(document.body.className)

	useEffect(() => {
		if (!shouldHighlight) {
			setProcessedHunks(hunks)
			return
		}
		let cancelled = false
		void Promise.all(hunks.map(async (hunk) => ({
			...hunk,
			highlightedOldLines: await highlightText(hunk.oldText, language, isLightTheme ? "light" : "dark"),
			highlightedNewLines: await highlightText(hunk.newText, language, isLightTheme ? "light" : "dark"),
		}))).then((value) => { if (!cancelled) setProcessedHunks(value) })
		return () => { cancelled = true }
	}, [hunks, language, isLightTheme, shouldHighlight])

	const rendered = processedHunks.length ? processedHunks : hunks
	const added = rendered.flatMap((hunk) => hunk.lines).filter((line) => line.type === "addition").length
	const removed = rendered.flatMap((hunk) => hunk.lines).filter((line) => line.type === "deletion").length

	return (
		<div className="capibara-diff-file" style={{ border: "1px solid var(--vscode-panel-border, transparent)", borderRadius: 4, overflow: "hidden" }}>
			<button type="button" onClick={() => setOpen((value) => !value)} className="flex items-center gap-1 w-full px-2 py-1.5 text-left" style={{ background: "var(--vscode-editorWidget-background)", color: "var(--vscode-foreground)", border: "none", cursor: "pointer" }}>
				{open ? <ChevronDown size={13} /> : <ChevronRight size={13} />}
				<code className="text-xs flex-1 truncate">{file.path}</code>
				<span className="text-[0.625rem]" style={{ color: "var(--vscode-descriptionForeground)" }}>+{added} -{removed}</span>
			</button>
			{open && <div className="capibara-diff-table overflow-x-auto max-h-72">
				<table className="w-full border-collapse text-xs" style={{ fontFamily: "var(--vscode-editor-font-family, monospace)" }}>
					<tbody>{rendered.flatMap((hunk, hunkIndex) => hunk.lines.map((line, lineIndex) => {
						const key = `${hunkIndex}-${lineIndex}`
						if (line.type === "gap") return <tr key={key}><td colSpan={4} className="px-2 italic" style={{ color: "var(--vscode-descriptionForeground)" }}>{line.hiddenCount} líneas ocultas</td></tr>
						const before = hunk.lines.slice(0, lineIndex).filter((item) => item.type !== "gap")
						const oldIndex = before.filter((item) => item.type === "deletion" || item.type === "context").length
						const newIndex = before.filter((item) => item.type === "addition" || item.type === "context").length
						const content = line.type === "deletion" ? hunk.highlightedOldLines?.[oldIndex] : line.type === "addition" ? hunk.highlightedNewLines?.[newIndex] : hunk.highlightedNewLines?.[newIndex] ?? hunk.highlightedOldLines?.[oldIndex]
						const background = line.type === "addition" ? "var(--vscode-diffEditor-insertedTextBackground, rgba(46, 160, 67, 0.16))" : line.type === "deletion" ? "var(--vscode-diffEditor-removedTextBackground, rgba(248, 81, 73, 0.16))" : "transparent"
						return <tr key={key} style={{ background }}><td className="px-1 text-right select-none" style={{ color: "var(--vscode-descriptionForeground)" }}>{line.oldLineNum ?? ""}</td><td className="px-1 text-right select-none" style={{ color: "var(--vscode-descriptionForeground)" }}>{line.newLineNum ?? ""}</td><td className="px-1 text-center select-none">{line.type === "addition" ? "+" : line.type === "deletion" ? "-" : ""}</td><td className="px-2 whitespace-pre">{content ?? line.content}</td></tr>
					}))}</tbody>
				</table>
			</div>}
		</div>
	)
}

export default DiffView
