import { ClipboardCopy } from "lucide-react"
import { t, type UiLanguage } from "../../i18n"

export interface FollowUpSuggestion {
	answer: string
}

export function FollowUpSuggest({ suggestions, selected, multiple = false, onSelect, language = "es" }: { suggestions: FollowUpSuggestion[]; selected: string | string[] | undefined; multiple?: boolean; onSelect: (answer: string) => void; language?: UiLanguage }) {
	if (!suggestions.length) return null
	const isSelected = (answer: string) => Array.isArray(selected) ? selected.includes(answer) : selected === answer
	return <div className="follow-up-suggestions" role={multiple ? "group" : "radiogroup"}>
		{suggestions.map((suggestion) => <div key={suggestion.answer} className="follow-up-suggestion-wrap">
			<button
				type="button"
				className={`follow-up-suggestion${isSelected(suggestion.answer) ? " is-selected" : ""}`}
				aria-pressed={isSelected(suggestion.answer)}
				onClick={() => onSelect(suggestion.answer)}>
				{suggestion.answer}
			</button>
			<button type="button" className="follow-up-copy" title={t(language, "chat.copySuggestion")} aria-label={t(language, "chat.copySuggestion")} onClick={() => void navigator.clipboard.writeText(suggestion.answer)}><ClipboardCopy size={12} /></button>
		</div>)}
	</div>
}
