import { z } from "zod"

import { rhsMessageSchema, queuedMessageSchema, tokenUsageSchema } from "./message.js"
import { modelInfoSchema } from "./model.js"
import { toolNamesSchema, toolUsageSchema } from "./tool.js"

/**
 * RhsAgentEventName
 */

export enum RhsAgentEventName {
	// Task Provider Lifecycle
	TaskCreated = "taskCreated",

	// Task Lifecycle
	TaskStarted = "taskStarted",
	TaskCompleted = "taskCompleted",
	TaskAborted = "taskAborted",
	TaskFocused = "taskFocused",
	TaskUnfocused = "taskUnfocused",
	TaskActive = "taskActive",
	TaskInteractive = "taskInteractive",
	TaskResumable = "taskResumable",
	TaskIdle = "taskIdle",

	// Subtask Lifecycle
	TaskPaused = "taskPaused",
	TaskUnpaused = "taskUnpaused",
	TaskSpawned = "taskSpawned",
	TaskDelegated = "taskDelegated",
	TaskDelegationCompleted = "taskDelegationCompleted",
	TaskDelegationResumed = "taskDelegationResumed",

	// Task Execution
	Message = "message",
	TaskModeSwitched = "taskModeSwitched",
	TaskAskResponded = "taskAskResponded",
	TaskUserMessage = "taskUserMessage",
	QueuedMessagesUpdated = "queuedMessagesUpdated",

	// Task Analytics
	TaskTokenUsageUpdated = "taskTokenUsageUpdated",
	TaskToolFailed = "taskToolFailed",

	// Configuration Changes
	ModeChanged = "modeChanged",
	ProviderProfileChanged = "providerProfileChanged",

	// Query Responses
	CommandsResponse = "commandsResponse",
	ModesResponse = "modesResponse",
	ModelsResponse = "modelsResponse",
}

/**
 * RhsAgentEvents
 */

export const rhsAgentEventsSchema = z.object({
	[RhsAgentEventName.TaskCreated]: z.tuple([z.string()]),

	[RhsAgentEventName.TaskStarted]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskCompleted]: z.tuple([
		z.string(),
		tokenUsageSchema,
		toolUsageSchema,
		z.object({
			isSubtask: z.boolean(),
		}),
	]),
	[RhsAgentEventName.TaskAborted]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskFocused]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskUnfocused]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskActive]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskInteractive]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskResumable]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskIdle]: z.tuple([z.string()]),

	[RhsAgentEventName.TaskPaused]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskUnpaused]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskSpawned]: z.tuple([z.string(), z.string()]),
	[RhsAgentEventName.TaskDelegated]: z.tuple([
		z.string(), // parentTaskId
		z.string(), // childTaskId
	]),
	[RhsAgentEventName.TaskDelegationCompleted]: z.tuple([
		z.string(), // parentTaskId
		z.string(), // childTaskId
		z.string(), // completionResultSummary
	]),
	[RhsAgentEventName.TaskDelegationResumed]: z.tuple([
		z.string(), // parentTaskId
		z.string(), // childTaskId
	]),

	[RhsAgentEventName.Message]: z.tuple([
		z.object({
			taskId: z.string(),
			action: z.union([z.literal("created"), z.literal("updated")]),
			message: rhsMessageSchema,
		}),
	]),
	[RhsAgentEventName.TaskModeSwitched]: z.tuple([z.string(), z.string()]),
	[RhsAgentEventName.TaskAskResponded]: z.tuple([z.string()]),
	[RhsAgentEventName.TaskUserMessage]: z.tuple([z.string()]),
	[RhsAgentEventName.QueuedMessagesUpdated]: z.tuple([z.string(), z.array(queuedMessageSchema)]),

	[RhsAgentEventName.TaskToolFailed]: z.tuple([z.string(), toolNamesSchema, z.string()]),
	[RhsAgentEventName.TaskTokenUsageUpdated]: z.tuple([z.string(), tokenUsageSchema, toolUsageSchema]),

	[RhsAgentEventName.ModeChanged]: z.tuple([z.string()]),
	[RhsAgentEventName.ProviderProfileChanged]: z.tuple([z.object({ name: z.string(), provider: z.string() })]),

	[RhsAgentEventName.CommandsResponse]: z.tuple([
		z.array(
			z.object({
				name: z.string(),
				source: z.enum(["global", "project", "built-in"]),
				filePath: z.string().optional(),
				description: z.string().optional(),
				argumentHint: z.string().optional(),
			}),
		),
	]),
	[RhsAgentEventName.ModesResponse]: z.tuple([z.array(z.object({ slug: z.string(), name: z.string() }))]),
	[RhsAgentEventName.ModelsResponse]: z.tuple([z.record(z.string(), modelInfoSchema)]),
})

export type RhsAgentEvents = z.infer<typeof rhsAgentEventsSchema>

/**
 * TaskEvent
 */

export const taskEventSchema = z.discriminatedUnion("eventName", [
	// Task Provider Lifecycle
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskCreated),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskCreated],
		taskId: z.number().optional(),
	}),

	// Task Lifecycle
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskStarted),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskStarted],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskCompleted),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskCompleted],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskAborted),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskAborted],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskFocused),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskFocused],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskUnfocused),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskUnfocused],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskActive),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskActive],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskInteractive),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskInteractive],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskResumable),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskResumable],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskIdle),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskIdle],
		taskId: z.number().optional(),
	}),

	// Subtask Lifecycle
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskPaused),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskPaused],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskUnpaused),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskUnpaused],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskSpawned),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskSpawned],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskDelegated),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskDelegated],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskDelegationCompleted),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskDelegationCompleted],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskDelegationResumed),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskDelegationResumed],
		taskId: z.number().optional(),
	}),

	// Task Execution
	z.object({
		eventName: z.literal(RhsAgentEventName.Message),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.Message],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskModeSwitched),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskModeSwitched],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskAskResponded),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskAskResponded],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.QueuedMessagesUpdated),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.QueuedMessagesUpdated],
		taskId: z.number().optional(),
	}),

	// Task Analytics
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskToolFailed),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskToolFailed],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.TaskTokenUsageUpdated),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.TaskTokenUsageUpdated],
		taskId: z.number().optional(),
	}),

	// Query Responses
	z.object({
		eventName: z.literal(RhsAgentEventName.CommandsResponse),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.CommandsResponse],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.ModesResponse),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.ModesResponse],
		taskId: z.number().optional(),
	}),
	z.object({
		eventName: z.literal(RhsAgentEventName.ModelsResponse),
		payload: rhsAgentEventsSchema.shape[RhsAgentEventName.ModelsResponse],
		taskId: z.number().optional(),
	}),
])

export type TaskEvent = z.infer<typeof taskEventSchema>
