import { useEffect, useMemo, useRef, useState } from "react"
import { ArrowRight, Check, ChevronDown, ChevronRight, ListChecks, SquareDashed, X } from "lucide-react"
import type { CapibaraTodoItem } from "../../types/messages"
import { t, type UiLanguage } from "../../i18n"

export function TodoListDisplay({ todos, defaultCollapsed = true, language = "es" }: { todos: CapibaraTodoItem[]; defaultCollapsed?: boolean; language?: UiLanguage }) {
	const [collapsed, setCollapsed] = useState(defaultCollapsed)
	const listRef = useRef<HTMLUListElement | null>(null)
	const itemRefs = useRef<Array<HTMLLIElement | null>>([])
	const currentIndex = useMemo(() => {
		const active = todos.findIndex((todo) => todo.status === "in_progress")
		return active >= 0 ? active : todos.findIndex((todo) => todo.status === "pending")
	}, [todos])
	const completed = todos.filter((todo) => todo.status === "completed").length
	const current = currentIndex >= 0 ? todos[currentIndex] : undefined

	useEffect(() => {
		if (collapsed || currentIndex < 0) return
		const list = listRef.current
		const item = itemRefs.current[currentIndex]
		if (!list || !item) return
		list.scrollTop = Math.max(0, item.offsetTop - list.offsetTop - (list.clientHeight - item.offsetHeight) / 2)
	}, [collapsed, currentIndex, todos])

	if (!todos.length) return null
	return <div className="todo-list-display" data-todo-list>
		<button type="button" className="todo-list-summary" onClick={() => setCollapsed((value) => !value)} aria-expanded={!collapsed}>
			{collapsed ? <ChevronRight size={13} /> : <ChevronDown size={13} />}
			<ListChecks size={13} />
			<span className="truncate flex-1">{completed === todos.length ? `${t(language, "chat.planCompleted")} (${completed})` : current?.text ?? t(language, "chat.workPlan")}</span>
			<span>{completed}/{todos.length}</span>
		</button>
		{!collapsed && <ul ref={listRef} className="todo-list-items">
			{todos.map((todo, index) => <li key={`${todo.text}-${index}`} ref={(element) => { itemRefs.current[index] = element }} className={todo.status === "in_progress" ? "is-current" : todo.status === "completed" ? "is-completed" : ""}>
				{todo.status === "cancelled" ? <X size={13} /> : todo.status === "completed" ? <Check size={13} /> : todo.status === "in_progress" ? <ArrowRight size={13} /> : <SquareDashed size={13} />}
				<span>{todo.text}</span>
			</li>)}
		</ul>}
	</div>
}
