import type { HostToWebview, WebviewToHost } from "./types/messages"

const HOST_EVENTS_WITH_TASK_CONTEXT = new Set<HostToWebview["type"]>([
	"streamStart",
	"streamChunk",
	"streamEnd",
	"turnStatus",
	"feedbackSaved",
	"activity",
	"contextUsage",
	"queueState",
	"condenseTaskContextStarted",
	"condenseTaskContextResponse",
	"imagesSelected",
	"imageSaved",
	"toolCallStart",
	"toolApprovalRequired",
	"toolStarted",
	"userQuestionRequired",
	"toolResult",
	"commandExecutionStatus",
	"error",
	"info",
])

const WEBVIEW_COMMANDS_WITH_TASK_CONTEXT = new Set<WebviewToHost["type"]>([
	"editMessage",
	"retryMessage",
	"assistantFeedback",
	"branchMessage",
	"exportQmd",
	"deleteMessage",
	"exportTask",
	"importTask",
	"cancelTask",
	"setMode",
	"chatMessage",
	"queueMessage",
	"removeQueuedMessage",
	"editQueuedMessage",
	"condenseTaskContextRequest",
	"selectImages",
	"openImage",
	"saveImage",
	"restoreCheckpoint",
	"invokeTool",
	"requestMentionFiles",
	"openMention",
])

export function acceptsHostMessageForTask(message: HostToWebview, activeTaskId: string): boolean {
	if (!HOST_EVENTS_WITH_TASK_CONTEXT.has(message.type) || !message.taskId || !activeTaskId) return true
	return message.taskId === activeTaskId
}

export function scopeWebviewMessage(message: WebviewToHost, activeTaskId: string): WebviewToHost {
	if (!activeTaskId || !WEBVIEW_COMMANDS_WITH_TASK_CONTEXT.has(message.type)) return message
	return { ...message, taskId: activeTaskId }
}
