/**
 * ToolUseBlock — wrapper reutilizable para bloques de herramienta.
 *
 * Portado del predecesor (Capibara). Provee un contenedor con borde
 * redondeado y fondo del editor. ToolUseBlockHeader es el header clickeable
 * con ícono, título y chevron.
 */

import type { ReactNode } from "react"

export interface ToolUseBlockProps {
	children: ReactNode
	className?: string
}

export function ToolUseBlock({ children, className = "" }: ToolUseBlockProps) {
	return (
		<div
			className={`overflow-hidden rounded-md border ${className}`}
			style={{
				background: "var(--vscode-editor-background)",
				borderColor: "var(--vscode-editorGroup-border, transparent)",
			}}>
			{children}
		</div>
	)
}

export interface ToolUseBlockHeaderProps {
	children: ReactNode
	onClick?: () => void
	className?: string
}

export function ToolUseBlockHeader({ children, onClick, className = "" }: ToolUseBlockHeaderProps) {
	return (
		<div
			role={onClick ? "button" : undefined}
			tabIndex={onClick ? 0 : undefined}
			onClick={onClick}
			onKeyDown={onClick ? (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onClick() } } : undefined}
			className={`flex items-center select-none text-sm px-3 py-2 ${onClick ? "cursor-pointer hover:brightness-110" : ""} ${className}`}
			style={{
				color: "var(--vscode-descriptionForeground)",
				fontFamily: "var(--vscode-editor-font-family, ui-monospace, SFMono-Regular, Menlo, monospace)",
			}}>
			{children}
		</div>
	)
}
