/**
 * Composer adaptado del predecesor.
 * Mantiene el protocolo pequeno de Cuy, pero usa la composicion real del
 * producto: editor amplio, rail de accion y controles secundarios discretos.
 */

import { useEffect, useMemo, useRef, useState } from "react"
import { BookOpen, Check, ChevronDown, Compass, Globe, ImagePlus, ListEnd, Plus, Search, SendHorizontal, Square, Type } from "lucide-react"
import type { ChatFontSize, CapibaraMentionFile, CapibaraSlashCommand, WebviewToHost } from "../types/messages"
import { t, type UiLanguage } from "../i18n"
import { activeFileMention, insertFileMention } from "../utils/mentions"

export interface ChatTextAreaProps {
	language: UiLanguage
	chatFontSize: ChatFontSize
	webEnabled: boolean
	mode: string
	modes: Array<{ slug: string; label: string; description: string }>
	slashCommands: CapibaraSlashCommand[]
	mentionFiles?: { query: string; requestId: string; items: CapibaraMentionFile[] }
	sendToHost: (msg: WebviewToHost) => void
	onSend: (text: string) => void
	onCancel?: () => void
	onSelectImages?: () => void
	selectedImages?: string[]
	streaming?: boolean
}

const MAX_HEIGHT = 260
const MODE_ICONS = {
	architect: BookOpen,
	ask: Search,
	code: Compass,
} as const

function ModeIcon({ slug, size = 14 }: { slug: string; size?: number }) {
	const Icon = MODE_ICONS[slug as keyof typeof MODE_ICONS] ?? Compass
	return <Icon size={size} aria-hidden="true" />
}

export function ChatTextArea({ language, chatFontSize, webEnabled, mode, modes, slashCommands, mentionFiles, sendToHost, onSend, onCancel, onSelectImages, selectedImages = [], streaming }: ChatTextAreaProps) {
	const [draft, setDraft] = useState("")
	const [cursor, setCursor] = useState(0)
	const [composerFocused, setComposerFocused] = useState(false)
	const [modeOpen, setModeOpen] = useState(false)
	const [slashOpen, setSlashOpen] = useState(false)
	const [slashIndex, setSlashIndex] = useState(0)
	const [mentionIndex, setMentionIndex] = useState(0)
	const textareaRef = useRef<HTMLTextAreaElement | null>(null)
	const popoverRef = useRef<HTMLDivElement | null>(null)
	const slashMenuRef = useRef<HTMLDivElement | null>(null)
	const mentionMenuRef = useRef<HTMLDivElement | null>(null)
	const mentionRequestSequence = useRef(0)
	const latestMentionRequest = useRef("")

	useEffect(() => {
		const element = textareaRef.current
		if (!element) return
		element.style.height = "auto"
		element.style.height = `${Math.min(Math.max(element.scrollHeight, 78), MAX_HEIGHT)}px`
	}, [draft])

	useEffect(() => {
		const clearComposerFocus = () => setComposerFocused(false)
		window.addEventListener("blur", clearComposerFocus)
		return () => window.removeEventListener("blur", clearComposerFocus)
	}, [])

	useEffect(() => {
		if (!modeOpen) return
		const handleClick = (event: MouseEvent) => {
			if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) setModeOpen(false)
		}
		document.addEventListener("mousedown", handleClick)
		return () => document.removeEventListener("mousedown", handleClick)
	}, [modeOpen])

	const slashQuery = draft.match(/^\/(\S*)$/)?.[1].toLowerCase() ?? ""
	const visibleSlashCommands = useMemo(
		() => slashCommands.filter((command) => command.name.toLowerCase().startsWith(slashQuery)),
		[slashCommands, slashQuery],
	)
	const activeMention = useMemo(() => activeFileMention(draft, cursor), [cursor, draft])
	const activeMentionQuery = activeMention?.query
	const visibleMentionFiles = mentionFiles?.requestId === latestMentionRequest.current && mentionFiles.query === (activeMentionQuery ?? "")
		? mentionFiles.items
		: []

	useEffect(() => {
		if (activeMentionQuery === undefined) return
		const requestId = `mention-${++mentionRequestSequence.current}`
		latestMentionRequest.current = requestId
		setMentionIndex(0)
		const timer = window.setTimeout(() => sendToHost({ type: "requestMentionFiles", query: activeMentionQuery, requestId }), 120)
		return () => window.clearTimeout(timer)
	}, [activeMentionQuery, sendToHost])

	useEffect(() => {
		const isSlashInvocation = draft.startsWith("/") && !draft.includes(" ") && !draft.includes("\n")
		if (!isSlashInvocation) {
			setSlashOpen(false)
			return
		}
		setSlashOpen(true)
		setSlashIndex(0)
		sendToHost({ type: "requestSlashCommands" })
	}, [draft, sendToHost])

	useEffect(() => {
		if (slashIndex < visibleSlashCommands.length) return
		setSlashIndex(Math.max(0, visibleSlashCommands.length - 1))
	}, [slashIndex, visibleSlashCommands.length])

	useEffect(() => {
		if (!slashOpen) return
		const handleClick = (event: MouseEvent) => {
			const target = event.target as Node
			if (!slashMenuRef.current?.contains(target) && target !== textareaRef.current) setSlashOpen(false)
		}
		document.addEventListener("mousedown", handleClick)
		return () => document.removeEventListener("mousedown", handleClick)
	}, [slashOpen])

	function selectSlashCommand(command: CapibaraSlashCommand): void {
		setDraft(`/${command.name} `)
		setSlashOpen(false)
		window.setTimeout(() => textareaRef.current?.focus(), 0)
	}

	function selectMention(item: CapibaraMentionFile): void {
		if (!activeMention) return
		const inserted = insertFileMention(draft, activeMention, item.path)
		setDraft(inserted.text)
		setCursor(inserted.cursor)
		window.setTimeout(() => {
			textareaRef.current?.focus()
			textareaRef.current?.setSelectionRange(inserted.cursor, inserted.cursor)
		}, 0)
	}

	function handleSend() {
		const text = draft.trim()
		if (!text) return
		onSend(text)
		setDraft("")
		setSlashOpen(false)
	}

	function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
		if (activeMention) {
			if (event.key === "Escape") {
				event.preventDefault()
				setCursor(activeMention.start)
				return
			}
			if (event.key === "ArrowDown" && visibleMentionFiles.length > 0) {
				event.preventDefault()
				setMentionIndex((index) => (index + 1) % visibleMentionFiles.length)
				return
			}
			if (event.key === "ArrowUp" && visibleMentionFiles.length > 0) {
				event.preventDefault()
				setMentionIndex((index) => (index - 1 + visibleMentionFiles.length) % visibleMentionFiles.length)
				return
			}
			if ((event.key === "Enter" || event.key === "Tab") && visibleMentionFiles[mentionIndex]) {
				event.preventDefault()
				selectMention(visibleMentionFiles[mentionIndex])
				return
			}
		}
		if (slashOpen) {
			if (event.key === "Escape") {
				event.preventDefault()
				setSlashOpen(false)
				return
			}
			if (event.key === "ArrowDown" && visibleSlashCommands.length > 0) {
				event.preventDefault()
				setSlashIndex((index) => (index + 1) % visibleSlashCommands.length)
				return
			}
			if (event.key === "ArrowUp" && visibleSlashCommands.length > 0) {
				event.preventDefault()
				setSlashIndex((index) => (index - 1 + visibleSlashCommands.length) % visibleSlashCommands.length)
				return
			}
			if ((event.key === "Enter" || event.key === "Tab") && visibleSlashCommands[slashIndex]) {
				event.preventDefault()
				selectSlashCommand(visibleSlashCommands[slashIndex])
				return
			}
		}
		if (event.key === "Enter" && !event.shiftKey) {
			event.preventDefault()
			handleSend()
		}
	}

	const activeMode = modes.find((item) => item.slug === mode)
	const canSend = Boolean(draft.trim() || selectedImages.length)

	return (
		<div className="chat-composer-shell relative px-2 pb-2">
			<div className="chat-composer">
				<div
					className={`chat-composer-input relative${composerFocused ? " is-focused" : ""}`}
					onPointerDownCapture={() => setComposerFocused(true)}
					onFocusCapture={() => setComposerFocused(true)}
					onBlurCapture={(event) => {
						if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setComposerFocused(false)
					}}>
					{slashOpen && (
						<div ref={slashMenuRef} className="composer-slash-menu" role="listbox" aria-label="Comandos disponibles">
							{visibleSlashCommands.length === 0 ? (
								<div className="composer-slash-empty">No hay comandos disponibles</div>
							) : visibleSlashCommands.map((command, index) => (
								<button
									key={`${command.source ?? "skill"}:${command.name}`}
									type="button"
									role="option"
									aria-selected={index === slashIndex}
									className={`composer-slash-option${index === slashIndex ? " is-selected" : ""}`}
									onMouseDown={(event) => event.preventDefault()}
									onClick={() => selectSlashCommand(command)}>
									<strong>/{command.name}</strong>
									{command.description && <small>{command.description}</small>}
								</button>
							))}
						</div>
					)}
					{activeMention && (
						<div ref={mentionMenuRef} className="composer-slash-menu composer-mention-menu" role="listbox" aria-label={t(language, "chat.projectFiles")}>
							{visibleMentionFiles.length === 0 ? (
								<div className="composer-slash-empty">{t(language, "chat.searchingFiles")}</div>
							) : visibleMentionFiles.map((item, index) => (
								<button
									key={item.path}
									type="button"
									role="option"
									aria-selected={index === mentionIndex}
									className={`composer-slash-option${index === mentionIndex ? " is-selected" : ""}`}
									onMouseDown={(event) => event.preventDefault()}
									onClick={() => selectMention(item)}>
									<strong>{item.label}</strong>
									<small>{item.description || "/"}</small>
								</button>
							))}
						</div>
					)}
					<textarea
						ref={textareaRef}
						value={draft}
						onChange={(event) => { setDraft(event.target.value); setCursor(event.target.selectionStart) }}
						onClick={(event) => setCursor(event.currentTarget.selectionStart)}
						onKeyUp={(event) => setCursor(event.currentTarget.selectionStart)}
						onKeyDown={handleKeyDown}
						placeholder={t(language, "chat.placeholder")}
						rows={3}
						autoFocus
						className="chat-textarea w-full resize-none text-sm"
						style={{ maxHeight: `${MAX_HEIGHT}px` }}
					/>
					<div className="chat-composer-actions">
						<button type="button" onClick={onSelectImages} title={t(language, "chat.attachImages")} aria-label={t(language, "chat.attachImages")} className="chat-queue-button"><ImagePlus size={15} /></button>
						{streaming && canSend && (
							<button
								type="button"
								onClick={handleSend}
								title={t(language, "chat.enqueueMessage")}
								aria-label={t(language, "chat.enqueueMessage")}
								className="chat-queue-button">
								<ListEnd size={15} />
							</button>
						)}
						<button
							type="button"
							onClick={streaming && onCancel ? onCancel : handleSend}
							disabled={!canSend && !streaming}
							title={t(language, streaming ? "app.cancelTaskShort" : "chat.send")}
							aria-label={t(language, streaming ? "app.cancelTaskShort" : "chat.send")}
							className={`chat-send-button${canSend || streaming ? " is-active" : ""}`}>
							{streaming ? <Square size={15} /> : <SendHorizontal size={16} />}
						</button>
					</div>
				</div>
				<div className="chat-composer-footer">
					<button type="button" onClick={() => sendToHost({ type: "newTask" })} title={t(language, "app.newTaskShort")} aria-label={t(language, "app.newTaskShort")} className="composer-icon-button"><Plus size={15} /></button>
					{modes.length > 0 && (
						<div className="relative" ref={popoverRef}>
							<button type="button" onClick={() => setModeOpen((open) => !open)} title={t(language, "chat.modes")} aria-label={t(language, "chat.modes")} aria-expanded={modeOpen} className="composer-mode-button"><ModeIcon slug={activeMode?.slug ?? mode} /><span>{activeMode?.label ?? mode}</span><ChevronDown size={13} /></button>
							{modeOpen && <div className="composer-mode-menu">{modes.map((item) => <button key={item.slug} type="button" onClick={() => { sendToHost({ type: "setMode", mode: item.slug }); setModeOpen(false) }} className={`composer-mode-option${item.slug === mode ? " is-selected" : ""}`}><ModeIcon slug={item.slug} /><span><strong>{item.label}</strong>{item.description && <small>{item.description}</small>}</span>{item.slug === mode && <Check size={13} />}</button>)}</div>}
						</div>
					)}
					<button type="button" onClick={() => sendToHost({ type: "toggleWeb" })} title={t(language, webEnabled ? "chat.webEnabled" : "chat.webDisabled")} aria-label={t(language, webEnabled ? "chat.webEnabled" : "chat.webDisabled")} aria-pressed={webEnabled} className={`composer-icon-button${webEnabled ? " is-enabled" : ""}`}><Globe size={15} /></button>
					<label className="composer-font-control" title={t(language, "settings.chatFontSize")}>
						<Type size={14} aria-hidden="true" />
						<select
							aria-label={t(language, "settings.chatFontSize")}
							value={chatFontSize}
							onChange={(event) => sendToHost({ type: "updateSetting", setting: "chat.fontSize", value: event.target.value })}>
							<option value="small">{t(language, "settings.fontSmall")}</option>
							<option value="normal">{t(language, "settings.fontNormal")}</option>
							<option value="large">{t(language, "settings.fontLarge")}</option>
							<option value="xlarge">{t(language, "settings.fontXLarge")}</option>
						</select>
					</label>
					<span className="composer-spacer" />
				</div>
			</div>
		</div>
	)
}
