/**
 * CodeAccordion — bloque de código expandible/colapsable.
 *
 * Portado del predecesor (Capibara). Header clickeable con path/language +
 * chevron, cuerpo con <pre><code> y botón copiar. Altura máxima colapsada
 * ~300px con scroll.
 */

import { useState } from "react"
import { ChevronDown, ChevronRight, Copy, Check } from "lucide-react"
import { ToolUseBlock, ToolUseBlockHeader } from "./ToolUseBlock"
import { SyntaxHighlightedCode } from "../CodeBlock"

export interface CodeAccordionProps {
	code: string
	language?: string
	path?: string
	title?: string
	defaultOpen?: boolean
	maxHeight?: number
}

export function CodeAccordion({ code, language, path, title, defaultOpen = false, maxHeight = 300 }: CodeAccordionProps) {
	const [expanded, setExpanded] = useState(defaultOpen)
	const [copied, setCopied] = useState(false)

	async function handleCopy(e: React.MouseEvent) {
		e.stopPropagation()
		try {
			await navigator.clipboard.writeText(code)
			setCopied(true)
			setTimeout(() => setCopied(false), 1500)
		} catch {
			/* clipboard puede no estar disponible en webview */
		}
	}

	const displayTitle = title || path || language || "code"
	const lineCount = code.split("\n").length

	return (
		<ToolUseBlock>
			<ToolUseBlockHeader onClick={() => setExpanded(!expanded)} className="group">
				{expanded ? <ChevronDown size={14} className="mr-1.5 flex-shrink-0" /> : <ChevronRight size={14} className="mr-1.5 flex-shrink-0" />}
				<span className="truncate mr-2">{displayTitle}</span>
				<span className="text-xs flex-shrink-0" style={{ opacity: 0.6 }}>
					{lineCount} líneas
				</span>
				<div className="flex-1" />
				<button
					type="button"
					onClick={handleCopy}
					title={copied ? "Copiado" : "Copiar"}
					className="flex items-center gap-1 rounded px-1.5 py-0.5 text-xs transition-colors opacity-0 group-hover:opacity-100 flex-shrink-0"
					style={{
						background: copied ? "var(--vscode-button-background)" : "var(--vscode-button-secondaryBackground)",
						color: copied ? "var(--vscode-button-foreground)" : "var(--vscode-button-secondaryForeground)",
						border: "1px solid var(--vscode-input-border, transparent)",
						cursor: "pointer",
					}}>
					{copied ? <Check size={10} /> : <Copy size={10} />}
					{copied ? "Copiado" : "Copiar"}
				</button>
			</ToolUseBlockHeader>
			{expanded && (
				<div className="overflow-x-auto" style={{ maxHeight: `${maxHeight}px`, overflowY: "auto" }}>
					<SyntaxHighlightedCode language={language} code={code} />
				</div>
			)}
		</ToolUseBlock>
	)
}
