export interface ActiveMention {
	query: string
	start: number
	end: number
}

export function activeFileMention(text: string, cursor: number): ActiveMention | undefined {
	const before = text.slice(0, cursor)
	const match = before.match(/(?:^|\s)(@\/(?:\\ |[^\s])*)$/)
	if (!match || match.index === undefined) return undefined
	const token = match[1]
	const start = match.index + match[0].lastIndexOf(token)
	return { query: token.slice(2).replace(/\\ /g, " "), start, end: cursor }
}

export function insertFileMention(text: string, active: ActiveMention, mentionPath: string): { text: string; cursor: number } {
	const replacement = `@${mentionPath} `
	const value = `${text.slice(0, active.start)}${replacement}${text.slice(active.end)}`
	return { text: value, cursor: active.start + replacement.length }
}

export function splitFileMentions(text: string): Array<{ text: string; mention?: string }> {
	const parts: Array<{ text: string; mention?: string }> = []
	const regex = /@\/((?:\\ |[^\s])+)/g
	let offset = 0
	for (const match of text.matchAll(regex)) {
		const index = match.index ?? 0
		if (index > offset) parts.push({ text: text.slice(offset, index) })
		parts.push({ text: match[0], mention: match[0] })
		offset = index + match[0].length
	}
	if (offset < text.length) parts.push({ text: text.slice(offset) })
	return parts.length ? parts : [{ text }]
}
