/**
 * TaskHeader — card colapsable con info de la tarea activa.
 *
 * Portado del predecesor (Capibara). Muestra el texto de la tarea
 * (primer mensaje del usuario), el modo activo, y botones de acción.
 * Colapsado por defecto, click expande/colapsa.
 */

import { useState } from "react"
import { BookOpen, ChevronDown, ChevronUp, Compass, Plus, Search, Shrink, Square } from "lucide-react"
import type { CapibaraChatMessage, CapibaraContextUsage, CapibaraTodoItem } from "../types/messages"
import { todosFromMessage } from "../types/messages"
import { t, type UiLanguage } from "../i18n"
import { ContextWindowProgress, formatTokens } from "./common/ContextWindowProgress"
import { TodoListDisplay } from "./common/TodoListDisplay"
import { MentionText } from "./common/MentionText"

export interface TaskHeaderProps {
	mode: string
	modeLabel: string
	messages: CapibaraChatMessage[]
	language: UiLanguage
	onNewTask: () => void
	onCondense: () => void
	onCancel: () => void
	streaming?: boolean
	contextUsage?: CapibaraContextUsage
	onOpenMention?: (path: string) => void
}

const MODE_ICONS = {
	architect: BookOpen,
	ask: Search,
	code: Compass,
} as const

function ModeIcon({ slug }: { slug: string }) {
	const Icon = MODE_ICONS[slug as keyof typeof MODE_ICONS] ?? Compass
	return <Icon size={12} aria-hidden="true" />
}

export function TaskHeader({ mode, modeLabel, messages, language, onNewTask, onCondense, onCancel, streaming, contextUsage, onOpenMention }: TaskHeaderProps) {
	const [expanded, setExpanded] = useState(false)

	// Extract task text from the first user message
	const firstUserMessage = messages.find((m) => m.role === "user")
	const taskText = firstUserMessage?.content ?? ""
	const todos = latestTodos(messages)

	if (!taskText) return null

	return (
		<div
			className="task-header mx-3 mt-2 rounded-xl border shadow-sm"
			style={{
				background: "var(--vscode-input-background)",
				borderColor: "var(--vscode-input-border, transparent)",
			}}>
			<div
				onClick={() => setExpanded(!expanded)}
				className="task-header-trigger flex items-center gap-2 w-full text-left bg-transparent border-none cursor-pointer px-3 pt-2 pb-2"
				style={{ color: "var(--vscode-foreground)" }}>
				{/* Mode badge */}
				<span
					className="task-mode-badge inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[0.625rem] font-semibold flex-shrink-0"
					style={{
						background: "var(--vscode-button-background)",
						color: "var(--vscode-button-foreground)",
					}}>
					<ModeIcon slug={mode} />
					{modeLabel}
				</span>

				{/* Task text — truncated when collapsed */}
				<span
					className="text-xs flex-1 min-w-0"
					style={{
						color: "var(--vscode-descriptionForeground)",
						overflow: "hidden",
						textOverflow: "ellipsis",
						whiteSpace: expanded ? "normal" : "nowrap",
					}}>
					<MentionText text={taskText} onOpen={onOpenMention} />
				</span>

				{/* Expand/collapse chevron */}
				{expanded ? (
					<ChevronUp size={14} className="flex-shrink-0" style={{ opacity: 0.5 }} />
				) : (
					<ChevronDown size={14} className="flex-shrink-0" style={{ opacity: 0.5 }} />
				)}
			</div>
			{!expanded && contextUsage && <div className="task-header-context-preview"><ContextWindowProgress usage={contextUsage} compact language={language} /></div>}

			{expanded && (
				<div className="px-3 pb-2">
					{contextUsage && <div className="mb-2"><ContextWindowProgress usage={contextUsage} compact language={language} /></div>}
					{contextUsage && <div className="task-local-metrics" aria-label={t(language, "chat.localMetrics")}>
						<span><strong>{t(language, "chat.tokenInput")}</strong>{formatTokens(contextUsage.totalInputTokens)}</span>
						<span><strong>{t(language, "chat.tokenOutput")}</strong>{formatTokens(contextUsage.totalOutputTokens)}</span>
						{contextUsage.cacheReadTokens > 0 && <span><strong>{t(language, "chat.cacheRead")}</strong>{formatTokens(contextUsage.cacheReadTokens)}</span>}
						{contextUsage.cacheWriteTokens > 0 && <span><strong>{t(language, "chat.cacheWritten")}</strong>{formatTokens(contextUsage.cacheWriteTokens)}</span>}
						{typeof contextUsage.totalCost === "number" && contextUsage.totalCost > 0 && <span><strong>{t(language, "chat.estimatedCost")}</strong>${contextUsage.totalCost.toFixed(4)}</span>}
					</div>}
					{todos.length > 0 && <TodoListDisplay todos={todos} language={language} />}
					<div className="flex items-center gap-2 mt-2">
					<button
						type="button"
						onClick={(e) => {
							e.stopPropagation()
							onNewTask()
						}}
						title={t(language, "app.newTaskShort")}
						className="flex items-center gap-1 rounded-md px-2.5 py-1 text-xs transition-colors"
						style={{
							background: "var(--vscode-button-secondaryBackground)",
							color: "var(--vscode-button-secondaryForeground)",
							border: "1px solid var(--vscode-input-border, transparent)",
							cursor: "pointer",
						}}>
						<Plus size={12} />
						{t(language, "app.newTaskShort")}
					</button>
					{!streaming && <button type="button" onClick={(e) => { e.stopPropagation(); onCondense() }} title={t(language, "chat.condenseContext")} aria-label={t(language, "chat.condenseContext")} className="flex items-center justify-center rounded-md p-1.5" style={{ background: "transparent", color: "var(--vscode-descriptionForeground)", border: "1px solid var(--vscode-input-border, transparent)", cursor: "pointer" }}><Shrink size={13} /></button>}
					{streaming && (
						<button
							type="button"
							onClick={(e) => {
								e.stopPropagation()
								onCancel()
							}}
							title={t(language, "app.cancelTaskShort")}
							className="flex items-center gap-1 rounded-md px-2.5 py-1 text-xs transition-colors"
							style={{
								background: "transparent",
								color: "var(--vscode-errorForeground)",
								border: "1px solid var(--vscode-errorForeground)",
								cursor: "pointer",
							}}>
							<Square size={12} />
							{t(language, "app.cancelTaskShort")}
						</button>
					)}
					</div>
				</div>
			)}
		</div>
	)
}

function latestTodos(messages: CapibaraChatMessage[]): CapibaraTodoItem[] {
	for (let index = messages.length - 1; index >= 0; index--) {
		const message = messages[index]
		const todos = todosFromMessage(message)
		if (todos !== undefined) return todos
	}
	return []
}
