import type { CapibaraState, WebviewToHost } from "../types/messages"
import { t } from "../i18n"

export function ChatGptAuthCard({ state, sendToHost }: {
	state: CapibaraState; sendToHost: (message: WebviewToHost) => void
}) {
	const auth = state.chatgptAuth ?? { status: "disconnected" }
	const waiting = auth.status === "requesting" || auth.status === "pending"
	return <section aria-label={t(state.language, "chatgpt.title")} className="grid gap-2 rounded border p-3 text-sm" aria-live="polite">
		<strong>{t(state.language, "chatgpt.title")}</strong>
		<p>{t(state.language, "chatgpt.hint")}</p>
		<p role="status">{t(state.language, `chatgpt.${auth.status}`)}</p>
		{auth.status === "pending" && <>
			<p>{t(state.language, "chatgpt.code")} <code className="select-text font-semibold">{auth.userCode}</code></p>
			<button type="button" onClick={() => sendToHost({ type: "chatgptAuthOpen" })}>{t(state.language, "chatgpt.open")}</button>
			<p className="text-xs">{t(state.language, "chatgpt.security")}</p>
		</>}
		{auth.status === "error" && <p role="alert">{t(state.language, auth.errorCode === "rate_limited" ? "chatgpt.rateLimit" : "chatgpt.failure")}</p>}
		{waiting
			? <button type="button" onClick={() => sendToHost({ type: "chatgptAuthCancel" })}>{t(state.language, "chatgpt.cancel")}</button>
			: <button type="button" onClick={() => sendToHost({ type: auth.status === "connected" ? "chatgptAuthDisconnect" : "chatgptAuthStart" })}>
				{t(state.language, auth.status === "connected" ? "chatgpt.disconnect" : "chatgpt.login")}
			</button>}
	</section>
}
