/**
 * CodeBlock — bloque de código con botón "copiar".
 *
 * Adaptado del renderer Markdown del predecesor: conserva GFM, matemáticas,
 * tablas desplazables, enlaces seguros y bloques de código copiables usando
 * únicamente tokens visuales del host.
 */

import { useEffect, useMemo, useState } from "react"
import ReactMarkdown from "react-markdown"
import rehypeKatex from "rehype-katex"
import remarkGfm from "remark-gfm"
import remarkMath from "remark-math"
import { Check, Copy } from "lucide-react"
import { toJsxRuntime } from "hast-util-to-jsx-runtime"
import { Fragment, jsx, jsxs } from "react/jsx-runtime"
import { getHighlighter, normalizeLanguage } from "../utils/highlighter"
import { MermaidBlock } from "./MermaidBlock"

export interface CodeBlockProps {
	language?: string
	code: string
}

type TabularRow = string[]

function parseTabularRow(line: string): TabularRow | undefined {
	if (!line.includes("\t")) return undefined

	const cells = line.split("\t").map((cell) => cell.trim())
	if (cells.length < 2 || cells.some((cell) => cell.length === 0)) return undefined

	return cells
}

/**
 * Some providers emit human-readable TSV instead of GFM tables. Convert only
 * consistent multi-row blocks outside fenced code so the Markdown renderer can
 * present them like ordinary tables without changing prose or code output.
 */
export function normalizeTabularMarkdown(text: string): string {
	const lines = text.split(/\r?\n/)
	const normalized: string[] = []
	let inFence = false
	let index = 0

	while (index < lines.length) {
		const line = lines[index]
		if (/^\s*```/.test(line)) {
			inFence = !inFence
			normalized.push(line)
			index += 1
			continue
		}

		const firstRow = inFence ? undefined : parseTabularRow(line)
		if (!firstRow) {
			normalized.push(line)
			index += 1
			continue
		}

		const rows: TabularRow[] = [firstRow]
		let end = index + 1
		while (end < lines.length) {
			const row = parseTabularRow(lines[end])
			if (!row) break
			rows.push(row)
			end += 1
		}

		const columnCount = firstRow.length
		const isConsistentBlock = rows.length >= 3 && rows.every((row) => row.length === columnCount)
		if (!isConsistentBlock) {
			normalized.push(line)
			index += 1
			continue
		}

		normalized.push(`| ${rows[0].join(" | ")} |`)
		normalized.push(`| ${rows[0].map(() => "---").join(" | ")} |`)
		for (const row of rows.slice(1)) {
			normalized.push(`| ${row.join(" | ")} |`)
		}
		index = end
	}

	return normalized.join("\n")
}

export function SyntaxHighlightedCode({ language, code }: CodeBlockProps) {
	const currentLanguage = normalizeLanguage(language)
	const fallback = useMemo(() => (
		<pre>
			<code className={`hljs language-${currentLanguage}`}>{code}</code>
		</pre>
	), [code, currentLanguage])
	const [highlightedCode, setHighlightedCode] = useState<React.ReactNode>(fallback)

	useEffect(() => {
		let mounted = true
		setHighlightedCode(fallback)

		async function highlight() {
			try {
				const highlighter = await getHighlighter(currentLanguage)
				const theme = document.body.className.toLowerCase().includes("light") ? "github-light" : "github-dark"
				const hast = highlighter.codeToHast(code, {
					lang: currentLanguage,
					theme,
				})
				if (!mounted) return

				setHighlightedCode(toJsxRuntime(hast, { Fragment, jsx, jsxs }))
			} catch (error) {
				console.error("[Cuy] Syntax highlighting failed:", error)
			}
		}

		highlight()
		return () => {
			mounted = false
		}
	}, [code, currentLanguage, fallback])

	return <div className="markdown-code-content">{highlightedCode}</div>
}

export function CodeBlock({ language, code }: CodeBlockProps) {
	const [copied, setCopied] = useState(false)

	async function handleCopy() {
		try {
			await navigator.clipboard.writeText(code)
			setCopied(true)
			setTimeout(() => setCopied(false), 1500)
		} catch {
			// clipboard API puede no estar disponible en webview; fallar silencioso
		}
	}

	return (
		<div
			className="relative my-2 rounded-md overflow-hidden border"
			style={{
				background: "var(--vscode-textCodeBlock-background, var(--vscode-editor-background))",
				borderColor: "var(--vscode-input-border, transparent)",
			}}>
			{language && (
				<div
					className="px-3 py-1 text-xs border-b"
					style={{
						color: "var(--vscode-descriptionForeground)",
						borderColor: "var(--vscode-input-border, transparent)",
						background: "var(--vscode-editor-background)",
					}}>
					{language}
				</div>
			)}
			<button
				type="button"
				onClick={handleCopy}
				title={copied ? "Copiado" : "Copiar"}
				aria-label={copied ? "Copiado" : "Copiar código"}
				className="markdown-copy-button absolute top-2 right-2 flex items-center justify-center rounded p-1.5 transition-colors"
				style={{
					background: copied ? "var(--vscode-button-background)" : "var(--vscode-button-secondaryBackground)",
					color: copied ? "var(--vscode-button-foreground)" : "var(--vscode-button-secondaryForeground)",
					border: "1px solid var(--vscode-input-border, transparent)",
					cursor: "pointer",
				}}>
				{copied ? <Check size={13} /> : <Copy size={13} />}
			</button>
			<SyntaxHighlightedCode language={language} code={code} />
		</div>
	)
}

/**
 * Markdown enriquecido para respuestas del agente: GFM, tablas, matemáticas y
 * bloques de código copiables. El renderizador conserva los tokens de tema del
 * host y no introduce un tema visual propio.
 */
export function Markdown({ text }: { text: string }) {
	return (
		<div className="markdown-content">
			<ReactMarkdown
				remarkPlugins={[[remarkGfm, { singleTilde: false }], remarkMath]}
				rehypePlugins={[rehypeKatex]}
				components={{
					table({ children, ...props }) {
						return (
							<div className="markdown-table-wrapper">
								<table {...props}>{children}</table>
							</div>
						)
					},
					pre({ children }) {
						const code = children as React.ReactElement<{ className?: string; children?: string }>
						const rawChildren: unknown = code?.props?.children
						const value = typeof rawChildren === "string"
							? rawChildren
							: Array.isArray(rawChildren)
								? rawChildren.filter((child): child is string => typeof child === "string").join("")
								: ""
						const language = code?.props?.className?.match(/language-([\w.+-]+)/)?.[1] ?? "text"
						if (language.toLowerCase() === "mermaid") return <MermaidBlock code={value.replace(/\n$/, "")} />
						return <CodeBlock language={language} code={value.replace(/\n$/, "")} />
					},
					code({ className, children, ...props }) {
						return <code className={className} {...props}>{children}</code>
					},
					a({ href, children, ...props }) {
						const external = Boolean(href && /^[a-z][a-z\d+.-]*:/i.test(href) && !href.startsWith("https://") && !href.startsWith("http://"))
						return <a href={href} target={external ? undefined : "_blank"} rel={external ? undefined : "noreferrer"} {...props}>{children}</a>
					},
				}}>
				{normalizeTabularMarkdown(text)}
			</ReactMarkdown>
		</div>
	)
}
