/**
 * Tipos del protocolo webview ↔ extension host.
 *
 * Fases 2 y 3:
 * - webview → host: `chatMessage`, `invokeTool` (Phase 3), `ready`, `requestState`, `openSettings`
 * - host → webview: `state` (snapshot inicial: provider/model/idioma/positron),
 *                   `streamStart`/`streamChunk`/`streamEnd` (chat streaming),
 *                   `toolResult` (Phase 3 — Positron data-science tools),
 *                   `error` (algo falló), `info` (notificación no-fatal)
 *
 * Plan §2.1: cuando llegue Fase 2.5+ se reescribe contra
 * `WebviewMessage` upstream con todas las actions (history, skills, modes, etc.).
 */

export type CapibaraMessageRole = "user" | "assistant" | "system" | "tool"
export type ResponseFeedback = "up" | "down"
export type ChatFontSize = "small" | "normal" | "large" | "xlarge"
export type CapibaraTodoStatus = "pending" | "in_progress" | "completed" | "cancelled"

export interface CapibaraTodoItem {
	text: string
	status: CapibaraTodoStatus
}

/** Display the authoritative full snapshot returned by the Python todo tool,
 * not a possibly partial merge request. Legacy Cuy inputs remain readable. */
export function todosFromMessage(message: CapibaraChatMessage): CapibaraTodoItem[] | undefined {
	if (message.toolOk === false || message.toolStatus === "error") return undefined
	if (message.toolName === "todo_list") {
		try {
			const result = JSON.parse(message.content)
			if (!Array.isArray(result.todos)) return undefined
			return result.todos.filter((item: any) => typeof item.content === "string"
				&& ["pending", "in_progress", "completed", "cancelled"].includes(item.status))
				.map((item: any) => ({ text: item.content, status: item.status }))
		} catch { return undefined }
	}
	if (message.toolName !== "update_todo_list") return undefined
	const input = message.toolInput as { todos?: CapibaraTodoItem[] } | undefined
	return Array.isArray(input?.todos) ? input.todos : undefined
}

export interface CapibaraQuestion {
	question: string
	options?: string[]
	allowMultiple?: boolean
}

export interface CapibaraApprovalPreviewFile {
	path: string
	original: string
	updated: string
	operation: "add" | "delete" | "update" | "move"
}

export interface CapibaraApprovalPreview {
	files: CapibaraApprovalPreviewFile[]
}

export type CapibaraApprovalReason = "none" | "requestLimit" | "cost" | "category" | "protectedPath"

export interface CapibaraChatMessage {
	id: string
	role: CapibaraMessageRole
	content: string
	timestamp: number
	streaming?: boolean
	toolName?: string
	toolOk?: boolean
	toolCallId?: string
	toolStatus?: "pending" | "awaiting_approval" | "awaiting_question" | "running" | "success" | "error" | "rejected"
	toolInput?: unknown
	messageIndex?: number
	feedback?: ResponseFeedback
	queued?: boolean
	images?: string[]
	approvalPreview?: CapibaraApprovalPreview
	approvalReason?: CapibaraApprovalReason
	commandExecutionId?: string
	commandStatus?: "started" | "output" | "exited" | "fallback" | "timeout" | "error"
	commandOutput?: string
	commandPid?: number
	commandExitCode?: number
	commandError?: string
	workspaceCheckpoint?: boolean
}

export interface CapibaraActivity {
	kind: "thinking" | "responding" | "tool"
	toolName?: string
	detail?: string
}

export interface CapibaraContextUsage {
	inputTokens: number
	contextWindow: number
	maxOutputTokens: number
	totalInputTokens: number
	totalOutputTokens: number
	cacheWriteTokens: number
	cacheReadTokens: number
	totalCost?: number
}

export interface CapibaraMentionFile {
	path: string
	label: string
	description: string
}

export interface CapibaraSlashCommand {
	name: string
	description?: string
	source?: string
}

export interface CapibaraState {
	chatgptAuth?: {
		status: "disconnected" | "requesting" | "pending" | "connected" | "cancelled" | "expired" | "error"
		flowId?: string
		userCode?: string
		verificationUri?: string
		errorCode?: string
	}
	provider: string
	modelId: string
	providerSettings: {
		modelId: string
		baseUrl?: string
		apiKeyConfigured: boolean
	}
	ollamaModels: string[]
	ollamaModelsLoading: boolean
	ollamaModelsError?: string
	language: "es" | "en"
	chatFontSize: ChatFontSize
	mode: string
	modes: Array<{ slug: string; label: string; description: string }>
	apiReady: boolean
	/** Phase 3: true when running inside Positron (`positron` module available). */
	positronAvailable: boolean
	webEnabled: boolean
	/** Phase 3: list of tool names the host has registered. */
	registeredTools: string[]
	autoApproval: {
		readOnly: boolean
		write: boolean
		execute: boolean
		requestLimit: number
	}
	accessPolicy: {
		profile: "restricted" | "workspace" | "full"
		approval: "always" | "sensitive" | "never"
	}
	/** Phase 4: resolved binary paths for the 4 external runners. */
	runners: {
		pdfstruct: string
		rhsRag: string
		rhsOkf: string
		obscura: string
	}
}

export interface CapibaraTaskSummary {
	id: string
	updatedAt: number
	messageCount: number
	preview: string
	title?: string
	checkpointCount?: number
	matchPreview?: string
	status?: "idle" | "running" | "completed" | "cancelled" | "error"
}

export type WebviewToHost = (
	| { type: "chatgptAuthStatus" | "chatgptAuthStart" | "chatgptAuthCancel" | "chatgptAuthDisconnect" | "chatgptAuthOpen" }
	| { type: "ready" }
	| { type: "chatMessage"; text: string; images?: string[] }
	| { type: "queueMessage"; text: string; images?: string[] }
	| { type: "removeQueuedMessage"; id: string }
	| { type: "editQueuedMessage"; payload: { id: string; text: string; images?: string[] } }
	| { type: "condenseTaskContextRequest" }
	| { type: "selectImages" }
	| { type: "openImage"; dataUri: string }
	| { type: "saveImage"; dataUri: string; defaultPath?: string }
	| { type: "restoreCheckpoint"; messageIndex: number }
	| { type: "requestState" }
	| { type: "requestOllamaModels" }
	| { type: "requestTasks"; query?: string }
	| { type: "requestSlashCommands" }
	| { type: "requestMentionFiles"; query: string; requestId: string }
	| { type: "openMention"; path: string }
	| { type: "resumeTask"; taskId: string }
	| { type: "deleteTask"; taskId: string }
	| { type: "exportTask"; taskId: string }
	| { type: "importTask" }
	| { type: "editMessage"; messageIndex: number; text: string }
	| { type: "retryMessage"; messageIndex: number }
	| { type: "assistantFeedback"; messageIndex: number; value: ResponseFeedback | null }
	| { type: "branchMessage"; messageIndex: number }
	| { type: "exportQmd"; messageIndex: number; mode: "create" | "append" }
	| { type: "deleteMessage"; messageIndex: number }
	| { type: "newTask" }
	| { type: "cancelTask" }
	| { type: "setMode"; mode: string }
	| { type: "toggleWeb" }
	| { type: "toolApproval"; callId: string; approved: boolean }
	| { type: "userQuestionResponse"; callId: string; answers: Record<string, string | string[]> }
	| { type: "invokeTool"; tool: string; params?: unknown }
	| { type: "openSettings" }
	| { type: "updateSetting"; setting: "provider" | "modelId" | "baseUrl" | "apiKey" | "language" | "chat.fontSize" | "autoApprove.readOnly" | "autoApprove.write" | "autoApprove.execute" | "autoApprove.requestLimit" | "permissions.profile" | "permissions.approval"; value: string | boolean | number }
) & { taskId?: string }

export type HostToWebview = (
	| { type: "chatgptAuth"; auth: NonNullable<CapibaraState["chatgptAuth"]> }
	| { type: "state"; state: CapibaraState }
	| { type: "ollamaModels"; models: string[]; loading: boolean; error?: string }
	| { type: "navigate"; tab: "chat" | "history" | "settings" }
	| { type: "tasks"; tasks: CapibaraTaskSummary[]; activeTaskId: string; query?: string }
	| { type: "history"; taskId: string; messages: CapibaraChatMessage[]; status?: "idle" | "running" | "completed" | "cancelled" | "error"; activity?: CapibaraActivity; contextUsage?: CapibaraContextUsage }
	| { type: "slashCommands"; commands: CapibaraSlashCommand[] }
	| { type: "mentionFiles"; query: string; requestId: string; items: CapibaraMentionFile[] }
	| { type: "streamStart"; messageId: string }
	| { type: "streamChunk"; messageId: string; delta: string }
	| { type: "streamEnd"; messageId: string; text?: string }
	| { type: "turnStatus"; status: "cancelled" | "error"; messageId?: string }
	| { type: "activity"; activity?: CapibaraActivity }
	| { type: "contextUsage"; contextUsage: CapibaraContextUsage }
	| { type: "queueState"; messages: Array<{ id: string; timestamp: number; text: string; images?: string[] }> }
	| { type: "condenseTaskContextStarted" }
	| { type: "condenseTaskContextResponse"; ok: boolean; message?: string }
	| { type: "imagesSelected"; images: string[] }
	| { type: "imageSaved"; path: string }
	| { type: "toolCallStart"; callId: string; tool: string; input: unknown }
	| { type: "toolApprovalRequired"; callId: string; tool: string; input: unknown; preview?: CapibaraApprovalPreview; approvalReason?: CapibaraApprovalReason }
	| { type: "toolStarted"; callId: string; tool: string }
	| { type: "userQuestionRequired"; callId: string; questions: CapibaraQuestion[] }
	| { type: "modeChanged"; mode: string }
	| { type: "webToggled"; enabled: boolean }
	| { type: "toolResult"; callId?: string; tool: string; ok: boolean; content: string }
	| { type: "commandExecutionStatus"; text: string }
	| { type: "error"; message: string }
	| { type: "info"; message: string }
	| { type: "feedbackSaved"; messageIndex: number; value: ResponseFeedback }
) & { taskId?: string }
