import type { CapibaraContextUsage } from "../../types/messages"
import { t, type UiLanguage } from "../../i18n"

export interface TokenDistribution {
	used: number
	reserved: number
	available: number
	usedPercent: number
	reservedPercent: number
	availablePercent: number
}

export function calculateTokenDistribution(usage: CapibaraContextUsage): TokenDistribution {
	const windowSize = Math.max(0, usage.contextWindow)
	if (windowSize === 0) return { used: 0, reserved: 0, available: 0, usedPercent: 0, reservedPercent: 0, availablePercent: 0 }
	const reserved = Math.min(windowSize, Math.max(0, usage.maxOutputTokens || Math.min(8_192, Math.floor(windowSize * 0.2))))
	const inputCapacity = Math.max(0, windowSize - reserved)
	const used = Math.min(inputCapacity, Math.max(0, usage.inputTokens))
	const available = Math.max(0, inputCapacity - used)
	return {
		used,
		reserved,
		available,
		usedPercent: used / windowSize * 100,
		reservedPercent: reserved / windowSize * 100,
		availablePercent: available / windowSize * 100,
	}
}

export function formatTokens(value: number): string {
	return new Intl.NumberFormat(undefined, { notation: value >= 10_000 ? "compact" : "standard", maximumFractionDigits: 1 }).format(Math.max(0, value))
}

export function ContextWindowProgress({ usage, compact = false, language = "es" }: { usage: CapibaraContextUsage; compact?: boolean; language?: UiLanguage }) {
	if (usage.contextWindow <= 0) return null
	const distribution = calculateTokenDistribution(usage)
	const inputCapacity = distribution.used + distribution.available
	const percent = inputCapacity > 0 ? Math.min(100, Math.round(distribution.used / inputCapacity * 100)) : 0
	const color = percent >= 85 ? "var(--vscode-errorForeground)" : percent >= 65 ? "var(--vscode-charts-yellow)" : "var(--vscode-foreground)"
	const title = [
		`${t(language, "chat.contextUsed")}: ${formatTokens(distribution.used)} tokens`,
		`${t(language, "chat.contextReserved")}: ${formatTokens(distribution.reserved)}`,
		`${t(language, "chat.contextAvailable")}: ${formatTokens(distribution.available)}`,
		`${t(language, "chat.contextWindow")}: ${formatTokens(usage.contextWindow)}`,
	].join("\n")

	return <div className={compact ? "context-progress compact" : "context-progress px-3 py-1"} role="status" aria-label={`${t(language, "chat.context")} ${percent}%`} title={title}>
		<div className="flex items-center justify-between text-[0.625rem]" style={{ color }}>
			<span>{t(language, "chat.context")}</span>
			<span>{compact ? `${percent}% · ${formatTokens(distribution.used)} / ${formatTokens(usage.contextWindow)}` : `${percent}%`}</span>
		</div>
		<div className="context-progress-track" aria-hidden="true">
			<div style={{ width: `${distribution.usedPercent}%`, background: color }} />
			<div style={{ width: `${distribution.reservedPercent}%`, background: "color-mix(in srgb, var(--vscode-foreground) 32%, transparent)" }} />
			<div style={{ width: `${distribution.availablePercent}%` }} />
		</div>
		{!compact && <div className="context-progress-legend">
			<span>{t(language, "chat.contextUsed")} {formatTokens(distribution.used)}</span>
			<span>{t(language, "chat.contextReserved")} {formatTokens(distribution.reserved)}</span>
			<span>{t(language, "chat.contextAvailable")} {formatTokens(distribution.available)}</span>
		</div>}
	</div>
}
