import { Fragment, useMemo } from "react"

interface TerminalOutputProps {
	content: string
}

const ANSI_COLORS: Record<number, string> = {
	30: "var(--vscode-terminal-ansiBlack, #000)", 31: "var(--vscode-terminal-ansiRed, #cd3131)", 32: "var(--vscode-terminal-ansiGreen, #0dbc79)",
	33: "var(--vscode-terminal-ansiYellow, #e5e510)", 34: "var(--vscode-terminal-ansiBlue, #2472c8)", 35: "var(--vscode-terminal-ansiMagenta, #bc3fbc)",
	36: "var(--vscode-terminal-ansiCyan, #11a8cd)", 37: "var(--vscode-terminal-ansiWhite, #e5e5e5)", 90: "var(--vscode-terminal-ansiBrightBlack, #666)",
	91: "var(--vscode-terminal-ansiBrightRed, #f14c4c)", 92: "var(--vscode-terminal-ansiBrightGreen, #23d18b)", 93: "var(--vscode-terminal-ansiBrightYellow, #f5f543)",
	94: "var(--vscode-terminal-ansiBrightBlue, #3b8eea)", 95: "var(--vscode-terminal-ansiBrightMagenta, #d670d6)", 96: "var(--vscode-terminal-ansiBrightCyan, #29b8db)",
	97: "var(--vscode-terminal-ansiBrightWhite, #fff)",
}

function ansiSegments(content: string): Array<{ text: string; color?: string; bold?: boolean }> {
	const segments: Array<{ text: string; color?: string; bold?: boolean }> = []
	let color: string | undefined
	let bold = false
	let cursor = 0
	// ANSI escape sequences are the protocol emitted by terminal programs.
	// eslint-disable-next-line no-control-regex
	const pattern = /\x1b\[([0-9;]*)m/g
	let match: RegExpExecArray | null
	while ((match = pattern.exec(content))) {
		if (match.index > cursor) segments.push({ text: content.slice(cursor, match.index), color, bold })
		for (const code of (match[1] ? match[1].split(";").map(Number) : [0])) {
			if (code === 0) { color = undefined; bold = false }
			else if (code === 1) bold = true
			else if (code === 22) bold = false
			else if (code === 39) color = undefined
			else if (ANSI_COLORS[code]) color = ANSI_COLORS[code]
		}
		cursor = match.index + match[0].length
	}
	if (cursor < content.length) segments.push({ text: content.slice(cursor), color, bold })
	return segments
}

export function TerminalOutput({ content }: TerminalOutputProps) {
	const segments = useMemo(() => ansiSegments(content), [content])
	return (
		<pre className="m-0 px-3 py-2 text-xs whitespace-pre-wrap break-words" style={{ color: "var(--vscode-terminal-foreground, var(--vscode-foreground))", background: "var(--vscode-terminal-background, transparent)", fontFamily: "var(--vscode-editor-font-family, monospace)", overflowX: "auto" }}>
			{segments.map((segment, index) => <Fragment key={index}><span style={{ color: segment.color, fontWeight: segment.bold ? 700 : undefined }}>{segment.text}</span></Fragment>)}
		</pre>
	)
}
