/**
 * TopBar — barra superior con brand, tabs de navegación y versión.
 *
 * Réplica del patrón de navegación del predecesor: tabs que cambian
 * entre vistas full-screen (chat, history, settings). Sin overlays.
 */

import { History, MessageSquare, Settings } from "lucide-react"
import { BRAND } from "../constants/capibara-brand"
import { t, type UiLanguage } from "../i18n"

export type Tab = "chat" | "history" | "settings"

export interface TopBarProps {
	activeTab: Tab
	onTabChange: (tab: Tab) => void
	language: UiLanguage
	accessPolicy: { profile: "restricted" | "workspace" | "full"; approval: "always" | "sensitive" | "never" }
}

const TABS: Array<{ id: Tab; icon: typeof MessageSquare; labelKey: "app.tabChat" | "app.tabHistory" | "app.tabSettings" }> = [
	{ id: "chat", icon: MessageSquare, labelKey: "app.tabChat" },
	{ id: "history", icon: History, labelKey: "app.tabHistory" },
	{ id: "settings", icon: Settings, labelKey: "app.tabSettings" },
]

export function TopBar({ activeTab, onTabChange, language, accessPolicy }: TopBarProps) {
	return (
		<div className="topbar">
			<div className="topbar-brand">
				<span className="topbar-brand-dot" />
				<span>{BRAND.shortName}</span>
				<span className="topbar-version">v{BRAND.version}</span>
			</div>

			<div className="topbar-tabs">
				<span className="text-[10px] opacity-70" title={`${accessPolicy.profile} · ${accessPolicy.approval}`}>
					{accessPolicy.profile === "full" ? "Full Access" : accessPolicy.profile === "restricted" ? "Restringido" : "Workspace"}
					{" · "}{accessPolicy.approval === "never" ? "No preguntar" : accessPolicy.approval === "always" ? "Preguntar" : "Sensibles"}
				</span>
				{TABS.map((tab) => {
					const Icon = tab.icon
					const isActive = activeTab === tab.id
					return (
						<button
							key={tab.id}
							type="button"
							onClick={() => onTabChange(tab.id)}
							title={t(language, tab.labelKey)}
							aria-label={t(language, tab.labelKey)}
							aria-pressed={isActive}
							className={`topbar-tab${isActive ? " active" : ""}`}>
							<Icon size={15} />
						</button>
					)
				})}
			</div>
		</div>
	)
}
