import { z } from "zod"

/**
 * Approval categories for Modo Auto consciente.
 *
 * Each flag controls whether the corresponding operation can be
 * auto-approved when the assistant is in `auto` mode. They are all
 * opt-in: `false` means the user must explicitly approve that operation.
 */
export const approvalCategoriesSchema = z.object({
	readFiles: z.boolean().default(false),
	writeFiles: z.boolean().default(false),
	executeCommands: z.boolean().default(false),
	useMcp: z.boolean().default(false),
	modeSwitch: z.boolean().default(false),
	subtasks: z.boolean().default(false),
	followupQuestions: z.boolean().default(false),
})

export type ApprovalCategories = z.infer<typeof approvalCategoriesSchema>

/**
 * Single source of truth for Capibara approval / "Modo Auto" behavior.
 *
 * The legacy fields (`autoApprovalEnabled`, `alwaysAllow*`, `allowedCommands`,
 * `deniedCommands`) remain in `GlobalSettings` during a transition window for
 * migration purposes, but new code should read this object instead.
 */
export const approvalStateSchema = z.object({
	mode: z.enum(["manual", "auto"]),
	/**
	 * Unix timestamp (ms) when the `auto` mode expires. Undefined means no
	 * expiration ("hasta cerrar sesión / manual"). Past values are treated as
	 * already expired.
	 */
	autoExpiresAt: z.number().optional(),
	categories: approvalCategoriesSchema,
	commandAllowlist: z.array(z.string()).default([]),
	commandDenylist: z.array(z.string()).default([]),
})

export type ApprovalState = z.infer<typeof approvalStateSchema>

/**
 * Default safe state: manual mode, all categories disabled, empty lists.
 */
export const DEFAULT_APPROVAL_STATE: ApprovalState = {
	mode: "manual",
	categories: {
		readFiles: false,
		writeFiles: false,
		executeCommands: false,
		useMcp: false,
		modeSwitch: false,
		subtasks: false,
		followupQuestions: false,
	},
	commandAllowlist: [],
	commandDenylist: [],
}
