/**
 * WelcomeView — pantalla de bienvenida de Capibara 4.
 *
 * Hero con el brand animado + tagline + tips de uso + preview de historial
 * reciente. Se muestra cuando no hay mensajes aún.
 */

import { Clock, MessageSquare, ReplaceAll, Users } from "lucide-react"
import { BRAND } from "../constants/capibara-brand"
import { t, type UiLanguage } from "../i18n"
import type { CapibaraTaskSummary } from "../types/messages"
import iconUrl from "../assets/capibara-icon.svg"

export interface WelcomeViewProps {
	language: UiLanguage
	tasks?: CapibaraTaskSummary[]
	onShowHistory?: () => void
}

const TIPS: Array<{ icon: typeof Users; titleKey: "welcome.tip1Title" | "welcome.tip2Title"; bodyKey: "welcome.tip1Body" | "welcome.tip2Body" }> = [
	{ icon: Users, titleKey: "welcome.tip1Title", bodyKey: "welcome.tip1Body" },
	{ icon: ReplaceAll, titleKey: "welcome.tip2Title", bodyKey: "welcome.tip2Body" },
]

function formatTime(ts: number): string {
	const d = new Date(ts)
	const now = new Date()
	const diffMs = now.getTime() - d.getTime()
	const diffMins = Math.floor(diffMs / 60000)
	if (diffMins < 1) return "ahora"
	if (diffMins < 60) return `hace ${diffMins} min`
	const diffHours = Math.floor(diffMins / 60)
	if (diffHours < 24) return `hace ${diffHours}h`
	const diffDays = Math.floor(diffHours / 24)
	if (diffDays < 7) return `hace ${diffDays}d`
	return d.toLocaleDateString()
}

export function WelcomeView({ language, tasks, onShowHistory }: WelcomeViewProps) {
	const recentTasks = tasks?.slice(0, 3) ?? []

	return (
		<div className="welcome-surface scrollable">
			<div className="welcome-copy animate-fade-in">
				<div className="welcome-mark" aria-hidden="true"><img src={iconUrl} alt="" /></div>
				<h1>{BRAND.shortName}</h1>
				<p className="welcome-tagline">{t(language, "welcome.tagline")}</p>
				<p className="welcome-about">{t(language, "welcome.subtitle")}</p>
				<div className="welcome-tips">
					{TIPS.map((tip) => {
						const Icon = tip.icon
						return <div key={tip.titleKey} className="welcome-tip"><Icon size={16} /><span><strong>{t(language, tip.titleKey)}</strong>: {t(language, tip.bodyKey)}</span></div>
					})}
				</div>
				{recentTasks.length > 0 && (
					<div className="welcome-history">
						<div className="welcome-history-label">{t(language, "welcome.recentTasks")}</div>
						{recentTasks.map((task) => <button key={task.id} type="button" onClick={onShowHistory} className="welcome-history-row"><span>{task.preview || task.id}</span><span><MessageSquare size={11} />{task.messageCount}<Clock size={11} />{formatTime(task.updatedAt)}</span></button>)}
					</div>
				)}
			</div>
		</div>
	)
}
