/**
 * App — entry point del webview. Conecta los componentes al bus del host.
 *
 * Navegación por tabs (chat / history / settings) estilo predecesor.
 * ChatView siempre montado para preservar estado. History y Settings
 * son vistas full-screen que reemplazan el chat, no overlays.
 *
 * Mantiene el protocolo de mensajes `WebviewToHost`/`HostToWebview` de capibara
 * intacto (crítico: el flujo OKF depende de él).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { ChatView } from "./components/ChatView"
import { SettingsView } from "./components/SettingsView"
import { HistoryView } from "./components/HistoryView"
import { TopBar, type Tab } from "./components/TopBar"
import type { CapibaraActivity, CapibaraChatMessage, CapibaraContextUsage, CapibaraMentionFile, CapibaraSlashCommand, CapibaraState, CapibaraTaskSummary, HostToWebview, WebviewToHost } from "./types/messages"
import { t } from "./i18n"
import { acceptsHostMessageForTask, scopeWebviewMessage } from "./taskMessageRouting"
import { commandExecutionStatusSchema, type CommandExecutionStatus } from "@capibara/types"

// Declare the global acquireVsCodeApi injected by VS Code at runtime.
// In dev/browser mode, this is undefined.
declare global {
	interface Window {
		acquireVsCodeApi?: () => {
			postMessage: (msg: unknown) => void
			getState: () => unknown
			setState: (state: unknown) => void
		}
	}
}

const FALLBACK_STATE: CapibaraState = {
	provider: "ollama",
	modelId: "",
	providerSettings: { modelId: "", baseUrl: "http://127.0.0.1:11434", apiKeyConfigured: false },
	ollamaModels: [],
	ollamaModelsLoading: false,
	language: "es",
	chatFontSize: "normal",
	mode: "code",
	modes: [],
	apiReady: false,
	positronAvailable: false,
	webEnabled: false,
	registeredTools: [],
	autoApproval: { readOnly: false, write: false, execute: false, requestLimit: 100 },
	accessPolicy: { profile: "workspace", approval: "sensitive" },
	runners: { pdfstruct: "?", rhsRag: "?", rhsOkf: "?", obscura: "?" },
}

function nextId(): string {
	return `msg-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
}

/**
 * Runtime history is authoritative, but a reconnect can deliver the same
 * terminal assistant row twice. Keep legitimate repeated answers from
 * separate turns while removing only adjacent, byte-identical duplicates.
 */
function normalizeHistory(messages: CapibaraChatMessage[]): CapibaraChatMessage[] {
	const normalized: CapibaraChatMessage[] = []
	for (const message of messages) {
		const previous = normalized.at(-1)
		const duplicateAssistant = previous?.role === "assistant"
			&& message.role === "assistant"
			&& previous.content === message.content
		const duplicateTool = previous?.role === "tool"
			&& message.role === "tool"
			&& previous.toolCallId
			&& previous.toolCallId === message.toolCallId
		if (duplicateAssistant || duplicateTool) continue
		normalized.push(message)
	}
	return normalized
}

/** Keep a runtime tool event attached to the assistant turn it belongs to.
 * Tool events can race the initial assistant placeholder or arrive after a
 * reconnect; in either case the tool row must remain before that response.
 */
function placeToolBeforeAssistant(messages: CapibaraChatMessage[], toolMessage: CapibaraChatMessage): CapibaraChatMessage[] {
	const withoutTool = messages.filter((message) => message.toolCallId !== toolMessage.toolCallId)
	const streamingAssistantIndex = withoutTool.findIndex((message) => message.role === "assistant" && message.streaming)
	const latestAssistantIndex = withoutTool.findLastIndex((message) => message.role === "assistant")
	const assistantIndex = streamingAssistantIndex >= 0 ? streamingAssistantIndex : latestAssistantIndex
	if (assistantIndex < 0) return [...withoutTool, toolMessage]
	return [...withoutTool.slice(0, assistantIndex), toolMessage, ...withoutTool.slice(assistantIndex)]
}

export default function App() {
	const vscode = useMemo(() => {
		try {
			return typeof window !== "undefined" ? window.acquireVsCodeApi?.() : undefined
		} catch {
			return undefined
		}
	}, [])

	const sendToHost = useCallback(
		(msg: WebviewToHost) => {
			if (vscode) {
				vscode.postMessage(msg)
			} else {
				console.info("[capibara → host]", msg)
			}
		},
		[vscode],
	)

	const [state, setState] = useState<CapibaraState>(FALLBACK_STATE)
	const [messages, setMessages] = useState<CapibaraChatMessage[]>([])
	const messagesRef = useRef<CapibaraChatMessage[]>([])
	const [activity, setActivity] = useState<CapibaraActivity | undefined>()
	const [contextUsage, setContextUsage] = useState<CapibaraContextUsage | undefined>()
	const [slashCommands, setSlashCommands] = useState<CapibaraSlashCommand[]>([])
	const [mentionFiles, setMentionFiles] = useState<{ query: string; requestId: string; items: CapibaraMentionFile[] }>({ query: "", requestId: "", items: [] })
	const [tasks, setTasks] = useState<CapibaraTaskSummary[]>([])
	const [activeTaskId, setActiveTaskId] = useState<string>("")
	const activeTaskIdRef = useRef("")
	const [retryableUserId, setRetryableUserId] = useState<string | undefined>()
	const [queuedCount, setQueuedCount] = useState(0)
	const [queuedMessages, setQueuedMessages] = useState<Array<{ id: string; timestamp: number; text: string; images?: string[] }>>([])
	const [selectedImages, setSelectedImages] = useState<string[]>([])
	const streamingRef = useRef(false)
	const [tab, setTab] = useState<Tab>("chat")

	useEffect(() => {
		sendToHost({ type: "ready" })
		sendToHost({ type: "requestState" })
		sendToHost({ type: "requestTasks" })
	}, [sendToHost])

	useEffect(() => {
		activeTaskIdRef.current = activeTaskId
	}, [activeTaskId])

	useEffect(() => {
		messagesRef.current = messages
	}, [messages])

	useEffect(() => {
		function onMessage(event: MessageEvent<HostToWebview>) {
			const msg = event.data
			if (!acceptsHostMessageForTask(msg, activeTaskIdRef.current)) return
			switch (msg.type) {
				case "state":
					setState(msg.state)
					break
				case "chatgptAuth":
					setState((prev) => ({ ...prev, chatgptAuth: msg.auth, apiReady: prev.provider === "openai-codex" ? msg.auth.status === "connected" && prev.apiReady : prev.apiReady }))
					break
				case "ollamaModels":
					setState((prev) => ({
						...prev,
						ollamaModels: msg.models,
						ollamaModelsLoading: msg.loading,
						ollamaModelsError: msg.error,
					}))
					break
				case "modeChanged":
					setState((prev) => ({ ...prev, mode: msg.mode }))
					break
				case "webToggled":
					setState((prev) => ({ ...prev, webEnabled: msg.enabled }))
					break
				case "navigate":
					setTab(msg.tab)
					break
				case "tasks":
					setTasks(msg.tasks)
					activeTaskIdRef.current = msg.activeTaskId
					setActiveTaskId(msg.activeTaskId)
					break
				case "history":
					activeTaskIdRef.current = msg.taskId
					setMessages((previous) => {
						const statusMessage = msg.status === "cancelled" || msg.status === "error"
							? { id: `turn-status-${msg.taskId}-${msg.status}`, role: "system" as const, content: t(state.language, msg.status === "cancelled" ? "chat.turnStopped" : "chat.turnFailed"), timestamp: Date.now() }
							: undefined
						const hasLiveStatus = statusMessage && previous.some((message) => message.id === statusMessage.id)
						const normalized = normalizeHistory(msg.messages)
						return statusMessage && !hasLiveStatus ? [...normalized, statusMessage] : normalized
					})
					// A persisted "running" status can survive an extension reload after
					// the actual turn has ended. Only live host activity may keep the
					// spinner and stop button visible.
					setActivity(msg.status === "running" ? msg.activity : undefined)
					setContextUsage(msg.contextUsage)
					setActiveTaskId(msg.taskId)
					setRetryableUserId(msg.status === "cancelled" || msg.status === "error" ? msg.messages.filter((message) => message.role === "user").at(-1)?.id : undefined)
					break
				case "slashCommands":
					setSlashCommands(msg.commands)
					break
				case "mentionFiles":
					setMentionFiles({ query: msg.query, requestId: msg.requestId, items: msg.items })
					break
				case "streamStart":
					setRetryableUserId(undefined)
					streamingRef.current = true
					setMessages((previous) => {
						const index = previous.findIndex((message) => message.role === "user" && message.queued)
						if (index < 0) return previous
						return previous.map((message, messageIndex) => messageIndex === index ? { ...message, queued: false } : message)
					})
					setActivity({ kind: "thinking" })
					setMessages((prev) => prev.some((message) => message.id === msg.messageId)
						? prev
						: [...prev, { id: msg.messageId, role: "assistant", content: "", timestamp: Date.now(), streaming: true }])
					break
				case "streamChunk":
					setActivity({ kind: "responding" })
					setMessages((prev) => prev.map((m) => (m.id === msg.messageId ? { ...m, content: m.content + msg.delta } : m)))
					break
				case "streamEnd":
					setActivity(undefined)
					streamingRef.current = false
					setMessages((prev) => normalizeHistory(prev.map((m) => (m.id === msg.messageId
						? { ...m, ...(typeof msg.text === "string" ? { content: msg.text } : {}), streaming: false }
						: m))))
					break
				case "turnStatus":
					setActivity(undefined)
					streamingRef.current = false
					setMessages((prev) => prev.filter((message) => !(message.role === "assistant" && message.streaming && !message.content.trim())))
					setRetryableUserId((previous) => previous ?? messagesRef.current.findLast((message) => message.role === "user")?.id)
					setMessages((previous) => {
						const statusMessage = { id: `turn-status-${msg.taskId}-${msg.status}`, role: "system" as const, content: t(state.language, msg.status === "cancelled" ? "chat.turnStopped" : "chat.turnFailed"), timestamp: Date.now() }
						return previous.some((message) => message.id === statusMessage.id) ? previous : [...previous, statusMessage]
					})
					break
				case "activity":
					setActivity(msg.activity)
					break
				case "contextUsage":
					setContextUsage(msg.contextUsage)
					break
					case "queueState":
						setQueuedMessages(msg.messages)
						setQueuedCount(msg.messages.length)
					break
				case "condenseTaskContextStarted":
					setActivity({ kind: "thinking", detail: "Condensando contexto" } as CapibaraActivity)
					break
				case "condenseTaskContextResponse":
					setActivity(undefined)
					break
				case "imagesSelected":
					setSelectedImages((previous) => [...previous, ...msg.images])
					break
				case "imageSaved":
					setMessages((previous) => [...previous, { id: nextId(), role: "system", content: `Imagen guardada en ${msg.path}`, timestamp: Date.now() }])
					break
				case "toolCallStart":
					setActivity({ kind: "tool", toolName: msg.tool })
					setMessages((previous) => {
						const toolMessage: CapibaraChatMessage = { id: `tool-${msg.callId}`, role: "tool", content: "", timestamp: Date.now(), toolName: msg.tool, toolCallId: msg.callId, toolStatus: "pending", toolInput: msg.input }
						const existing = previous.find((message) => message.toolCallId === msg.callId)
						return placeToolBeforeAssistant(previous, existing ? { ...existing, toolName: msg.tool, toolInput: msg.input } : toolMessage)
					})
					break
				case "toolApprovalRequired":
					setActivity(undefined)
					setMessages((prev) => {
						if (prev.some((m) => m.toolCallId === msg.callId)) {
								const existing = prev.find((m) => m.toolCallId === msg.callId)!
								return placeToolBeforeAssistant(prev, { ...existing, toolName: msg.tool, toolInput: msg.input, toolStatus: "awaiting_approval", approvalPreview: msg.preview, approvalReason: msg.approvalReason })
						}
						return placeToolBeforeAssistant(prev, {
								id: `approval-${msg.callId}`,
								role: "tool",
								content: "",
								timestamp: Date.now(),
								toolName: msg.tool,
								toolCallId: msg.callId,
									toolStatus: "awaiting_approval",
									toolInput: msg.input,
								approvalPreview: msg.preview,
								approvalReason: msg.approvalReason,
						})
					})
					break
				case "userQuestionRequired":
					setActivity(undefined)
					setMessages((prev) => placeToolBeforeAssistant(prev, {
							id: `question-${msg.callId}`,
							role: "tool",
							content: "",
							timestamp: Date.now(),
							toolName: "ask_user_question",
							toolCallId: msg.callId,
							toolStatus: "awaiting_question",
							toolInput: msg.questions,
					}))
					break
				case "toolStarted":
					setActivity({ kind: "tool", toolName: msg.tool })
					setMessages((previous) => previous.map((message) => message.toolCallId === msg.callId ? { ...message, toolStatus: "running" } : message))
					break
				case "commandExecutionStatus": {
					let parsed: CommandExecutionStatus | undefined
					try {
						const candidate = commandExecutionStatusSchema.safeParse(JSON.parse(msg.text))
						if (candidate.success) parsed = candidate.data
					} catch {
						// Progress is optional; the final tool result remains authoritative.
					}
					if (!parsed) break
					const detail = parsed.status === "started"
						? `Ejecutando: ${parsed.command}`
						: parsed.status === "output" ? "Recibiendo salida del terminal" : "Procesando resultado del terminal"
					setActivity({ kind: "tool", toolName: "execute_command", detail })
					setMessages((previous) => {
						let targetIndex = -1
						for (let index = previous.length - 1; index >= 0; index--) {
							const message = previous[index]
							if (message.role === "tool" && message.toolName === "execute_command" && (!message.commandExecutionId || message.commandExecutionId === parsed!.executionId)) {
								targetIndex = index
								break
							}
						}
						if (targetIndex < 0) return previous
						return previous.map((message, index) => {
							if (index !== targetIndex) return message
							const next = { ...message, commandExecutionId: parsed!.executionId, commandStatus: parsed!.status }
							if (parsed!.status === "started") return { ...next, commandPid: parsed!.pid }
							if (parsed!.status === "output") return { ...next, commandOutput: parsed!.output }
							if (parsed!.status === "exited") return { ...next, commandExitCode: parsed!.exitCode }
							if (parsed!.status === "error") return { ...next, commandError: parsed!.message }
							return next
						})
					})
					break
				}
				case "feedbackSaved":
					setMessages((previous) => previous.map((message) => message.messageIndex === msg.messageIndex ? { ...message, feedback: msg.value } : message))
					break
				case "error":
					setActivity(undefined)
					setMessages((prev) => [
						...prev.filter((message) => !(message.role === "assistant" && message.streaming && !message.content.trim())),
						{ id: nextId(), role: "system", content: `Error: ${msg.message}`, timestamp: Date.now() },
					])
					break
				case "toolResult":
					setActivity({ kind: "thinking" })
					if (msg.callId) {
						setMessages((previous) => {
							const existing = previous.find((message) => message.toolCallId === msg.callId)
							const toolMessage: CapibaraChatMessage = existing
								? { ...existing, content: msg.content, toolName: msg.tool, toolOk: msg.ok, toolStatus: msg.ok ? "success" : "error" }
								: { id: `tool-${msg.callId}`, role: "tool", content: msg.content, timestamp: Date.now(), toolName: msg.tool, toolCallId: msg.callId, toolOk: msg.ok, toolStatus: msg.ok ? "success" : "error" }
							return placeToolBeforeAssistant(previous, toolMessage)
						})
					}
					break
				case "info":
					setActivity(undefined)
					setMessages((prev) => [
						...prev,
						{ id: nextId(), role: "system", content: msg.message, timestamp: Date.now() },
					])
					break
			}
		}

		if (vscode) {
			window.addEventListener("message", onMessage)
			return () => window.removeEventListener("message", onMessage)
		}
		return undefined
	}, [state.language, vscode])

	useEffect(() => {
		function handler() {
			sendToHost({ type: "openSettings" })
		}
		window.addEventListener("capibara-open-settings", handler)
		return () => window.removeEventListener("capibara-open-settings", handler)
	}, [sendToHost])

	const wrappedSendToHost = useCallback(
		(msg: WebviewToHost) => {
				if (msg.type === "chatMessage" || msg.type === "queueMessage") {
					setRetryableUserId(undefined)
					const queued = msg.type === "queueMessage" || streamingRef.current
					if (queued) setQueuedCount((count) => count + 1)
				setMessages((prev) => [...prev, { id: nextId(), role: "user", content: msg.text, timestamp: Date.now(), queued, images: msg.images }])
					setSelectedImages([])
			}
			sendToHost(scopeWebviewMessage(msg, activeTaskIdRef.current))
		},
		[sendToHost],
	)

	// The assistant's temporary streaming row is not persisted in task history.
	// A restored activity therefore also means the active turn is still running.
	const streaming = messages.some((m) => m.streaming) || Boolean(activity)

	return (
		<div lang={state.language} className="fixed top-0 left-0 right-0 bottom-0 flex flex-col" style={{ background: "var(--background)", color: "var(--foreground)" }}>
			<TopBar activeTab={tab} onTabChange={setTab} language={state.language} accessPolicy={state.accessPolicy} />
			{/* ChatView always mounted to preserve message state */}
			<div className={tab !== "chat" ? "hidden" : "flex-1 min-h-0 flex flex-col"}>
				<ChatView
					messages={messages}
					sendToHost={wrappedSendToHost}
					language={state.language}
					chatFontSize={state.chatFontSize}
					webEnabled={state.webEnabled}
					mode={state.mode}
					modes={state.modes}
					slashCommands={slashCommands}
					mentionFiles={mentionFiles}
					tasks={tasks}
					queuedCount={queuedCount}
					queuedMessages={queuedMessages}
					activity={activity}
					contextUsage={contextUsage}
					retryableUserId={retryableUserId}
					onShowHistory={() => setTab("history")}
					streaming={streaming}
					selectedImages={selectedImages}
					onSelectImages={() => sendToHost(scopeWebviewMessage({ type: "selectImages" }, activeTaskIdRef.current))}
				/>
			</div>

			{tab === "history" && (
				<div className="flex-1 min-h-0 flex flex-col">
					<HistoryView
						language={state.language}
						tasks={tasks}
						activeTaskId={activeTaskId}
						sendToHost={sendToHost}
						onClose={() => setTab("chat")}
					/>
				</div>
			)}

			{tab === "settings" && (
				<div className="flex-1 min-h-0 flex flex-col">
					<SettingsView state={state} sendToHost={sendToHost} onClose={() => setTab("chat")} />
				</div>
			)}
		</div>
	)
}
